1	/* Phase 1: hero scroll animation. Phase 2: theme tokens, fonts and the headline. Phase 3: aayat on the pages. */
2	
3	*,
4	*::before,
5	*::after {
6	  box-sizing: border-box;
7	}
8	
9	/* Dark theme, from design-system/quran-landing/MASTER.md. The background is the footage's own #1F1A18
10	   rather than MASTER's #1C1917 (three shades apart), so the frame's edges disappear without a blend.
11	   Cinzel for the headline and the bright gold were chosen by the user from on-page options. */
12	:root {
13	  --color-background: #1F1A18;
14	  --color-foreground: #FAFAF9;
15	  --color-muted-foreground: #A8A29E;
16	  --color-accent: #D4AF37;
17	  --font-display: Cinzel, 'Trajan Pro', Georgia, serif;
18	  --font-body: Jost, system-ui, sans-serif;
19	  --font-arabic: 'Amiri Quran', 'Scheherazade New', serif;
20	  color-scheme: dark;
21	}
22	
23	html,
24	body {
25	  margin: 0;
26	  background: var(--color-background);
27	  color: var(--color-foreground);
28	  font-family: var(--font-body);
29	}
30	
31	/* No scroll bar: it broke the dark scene. Scrolling works the same without it. */
32	html {
33	  scrollbar-width: none;
34	}
35	
36	html::-webkit-scrollbar {
37	  display: none;
38	}
39	
40	/* A tall section; the stage inside it stays pinned while it scrolls past. Its height is one screen
41	   plus the timeline in main.js (4.1 screens): the rest, the opening, then one group of aayat, before
42	   the page moves on. Phones scroll two thirds as far, because a finger moves further per swipe than
43	   a mouse wheel per click. */
44	.hero {
45	  position: relative;
46	  height: 510vh;
47	}
48	
49	.stage {
50	  position: sticky;
51	  top: 0;
52	  height: 100vh;
53	  height: 100svh; /* the book stays whole behind mobile browser bars */
54	  overflow: hidden;
55	}
56	
57	/* The book and its aayat sit together in .subject, which atmosphere.js moves slightly while nobody is
58	   scrolling. The light in the air is a second canvas over everything, and never catches clicks. */
59	.subject,
60	.air {
61	  position: absolute;
62	  inset: 0;
63	}
64	
65	.subject canvas,
66	.air {
67	  display: block;
68	  width: 100%;
69	  height: 100%;
70	}
71	
72	.air {
73	  pointer-events: none;
74	}
75	
76	/* The headline, centred in the space under the closed book. --book-h is the book's height on screen,
77	   set by main.js, which also fades it out as the cover starts to open. */
78	.wordmark {
79	  position: absolute;
80	  z-index: 1; /* over .subject: the frame's feathered bottom edge reaches the headline on some screens */
81	  left: 0;
82	  right: 0;
83	  bottom: calc((50% - var(--book-h, 60svh) / 2) / 2);
84	  transform: translateY(50%);
85	  padding: 0 1.5rem;
86	  text-align: center;
87	}
88	
89	.wordmark h1 {
90	  margin: 0;
91	  padding-left: 0.2em; /* balances the letter-spacing after the last letter, so the text sits truly centred */
92	  font-family: var(--font-display);
93	  font-size: clamp(1.125rem, 0.9rem + 1vw, 1.625rem);
94	  font-weight: 500;
95	  line-height: 1.2;
96	  letter-spacing: 0.2em;
97	  text-transform: uppercase;
98	  color: var(--color-accent);
99	}
100	
101	.wordmark p {
102	  margin: 0.7em 0 0;
103	  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
104	  font-weight: 300;
105	  letter-spacing: 0.06em;
106	  color: var(--color-muted-foreground);
107	}
108	
109	/* Aayat, laid over the open book's pages. The numbers are page positions in the 1280x720 footage:
110	   left page x 262-636, right page x 645-1020, both y 80-640. main.js sets --s (the book's scale) and
111	   --x0/--y0 (where the footage's corner sits once the book is open), and each group's opacity. */
112	.aayat {
113	  position: absolute;
114	  inset: 0;
115	  pointer-events: none;
116	}
117	
118	.group {
119	  position: absolute;
120	  inset: 0;
121	  opacity: 0;
122	  transition: opacity 600ms cubic-bezier(0.32, 0.72, 0, 1); /* main.js only switches opacity between 0 and 1 */
123	  mix-blend-mode: multiply; /* the ink sits in the paper, so the paper's shading shows through it */
124	}
125	
126	.page {
127	  position: absolute;
128	  top: calc(var(--y0, 0px) + 80px * var(--s, 1));
129	  width: calc(375px * var(--s, 1));
130	  height: calc(560px * var(--s, 1));
131	  padding: calc(56px * var(--s, 1)) calc(40px * var(--s, 1));
132	  display: flex;
133	  flex-direction: column;
134	  justify-content: safe center;
135	  gap: 1.25em;
136	  overflow: hidden;
137	  text-align: center;
138	  color: #2B211B; /* dark ink, 14:1 on the cream page */
139	}
140	
141	.page p {
142	  margin: 0;
143	}
144	
145	.page.right {
146	  left: calc(var(--x0, 0px) + 645px * var(--s, 1));
147	  font-size: calc(30px * var(--s, 1));
148	}
149	
150	.page.left {
151	  left: calc(var(--x0, 0px) + 262px * var(--s, 1));
152	  font-size: calc(16px * var(--s, 1));
153	}
154	
155	.arabic {
156	  font-family: var(--font-arabic);
157	  line-height: 2.2; /* room for the marks above and below the letters */
158	}
159	
160	.marker {
161	  color: #A16207; /* gold only for the small accents */
162	}
163	
164	.surah {
165	  padding-left: 0.15em;
166	  font-family: var(--font-display);
167	  font-size: 1.2em;
168	  letter-spacing: 0.15em;
169	  text-transform: uppercase;
170	  color: #8A6A1F;
171	}
172	
173	.meaning {
174	  display: none;
175	  font-weight: 400;
176	  line-height: 1.6;
177	  color: #3A302A;
178	}
179	
180	.ref {
181	  font-size: 0.85em;
182	  letter-spacing: 0.08em;
183	  color: #6B5E55;
184	}
185	
186	@media (max-width: 767px) {
187	  .hero {
188	    height: 373vh; /* one screen plus two thirds of 4.1 */
189	  }
190	
191	  /* The pages are too small for a second block of text, so the left page's text sits under the book. */
192	  .group {
193	    mix-blend-mode: normal;
194	  }
195	
196	  .page.left {
197	    left: 1.5rem;
198	    right: 1.5rem;
199	    width: auto;
200	    top: calc(var(--y0, 0px) + 650px * var(--s, 1) + 1rem);
201	    height: calc(var(--y0, 0px) + 70px * var(--s, 1) - 2rem);
202	    padding: 0;
203	    font-size: 0.875rem;
204	    color: var(--color-muted-foreground);
205	  }
206	
207	  .page.left .surah {
208	    color: var(--color-accent);
209	  }
210	
211	  .page.left .meaning,
212	  .page.left .ref {
213	    color: var(--color-muted-foreground);
214	  }
215	}
216	
217	/* Reduced motion: no scrubbing, just the open book with a random group of aayat. */
218	.still .hero {
219	  height: auto;
220	}
221	
222	.still .group {
223	  transition: none;
224	}
225	
226	/* TRYOUT: phase 3 options, set on <html> by main.js. Once the user picks, move the picks above and
227	   delete everything below. */
228	[data-arabic='scheherazade'] {
229	  --font-arabic: 'Scheherazade New', 'Amiri Quran', serif;
230	}
231	
232	[data-left='meaning'] .meaning {
233	  display: block;
234	}
235	
236	/* Phase 4, "Aayat while moving: Fix B" (set by atmosphere.js): plain ink, as on phones. */
237	[data-ink='flat'] .group {
238	  mix-blend-mode: normal;
239	}
240	
241	.tryout input[type='range'] {
242	  width: 10em;
243	  accent-color: #d4af37;
244	}
245	
246	.tryout output {
247	  min-width: 7em;
248	  font-variant-numeric: tabular-nums;
249	}
250	
251	.tryout {
252	  position: fixed;
253	  right: 12px; /* bottom-right, clear of the headline picker (wordmark-options.js) in the bottom-left */
254	  bottom: 12px;
255	  max-width: calc(100vw - 24px);
256	  max-height: calc(100svh - 24px); /* scrolls inside itself on a phone */
257	  overflow-y: auto;
258	  padding: 10px 12px;
259	  border: 1px solid #3F3A37;
260	  border-radius: 12px;
261	  background: rgba(0, 0, 0, 0.7);
262	  font: 13px/1 system-ui, sans-serif;
263	  color: #e7e0d8;
264	}
265	
266	.tryout .readout {
267	  max-width: 34em;
268	  margin: 10px 0 2px;
269	  line-height: 1.4;
270	  color: #A8A29E;
271	  font-variant-numeric: tabular-nums;
272	}
273	
274	.tryout summary {
275	  padding: 4px 0;
276	  cursor: pointer;
277	}
278	
279	.tryout div {
280	  display: flex;
281	  flex-wrap: wrap;
282	  align-items: center;
283	  gap: 6px;
284	  margin-top: 8px;
285	}
286	
287	.tryout span {
288	  min-width: 10em;
289	  color: #A8A29E;
290	}
291	
292	.tryout button {
293	  padding: 10px 14px;
294	  border: 1px solid #5c5048;
295	  border-radius: 999px;
296	  background: transparent;
297	  color: #e7e0d8;
298	  font: inherit;
299	  cursor: pointer;
300	}
301	
302	.tryout button[aria-pressed='true'] {
303	  border-color: #d4af37;
304	  color: #d4af37;
305	}
306	
307	/* TRYOUT, phones only: how far to scroll through the hero, and where the surah name goes. */
308	@media (max-width: 767px) {
309	  [data-phone-scroll='medium']:not(.still) .hero {
310	    height: 310vh;
311	  }
312	
313	  [data-phone-scroll='short']:not(.still) .hero {
314	    height: 250vh;
315	  }
316	
317	  [data-phone-left='page'] .page.left {
318	    left: calc(var(--x0, 0px) + 262px * var(--s, 1));
319	    right: auto;
320	    top: calc(var(--y0, 0px) + 80px * var(--s, 1));
321	    width: calc(375px * var(--s, 1));
322	    height: calc(560px * var(--s, 1));
323	    padding: calc(56px * var(--s, 1)) calc(16px * var(--s, 1));
324	    font-size: max(9px, calc(16px * var(--s, 1)));
325	    color: #2B211B;
326	  }
327	
328	  [data-phone-left='page'] .page.left .surah {
329	    color: #8A6A1F;
330	  }
331	
332	  [data-phone-left='page'] .page.left .ref {
333	    color: #6B5E55;
334	  }
335	
336	  [data-phone-left='page'] .page.left .meaning {
337	    display: none; /* too long for a page this small */
338	  }
339	}
