   Cinzel for the headline and the bright gold were chosen by the user from on-page options. */
:root {
  --color-background: #1F1A18;
  --color-foreground: #FAFAF9;
  --color-muted-foreground: #A8A29E;
  --color-accent: #D4AF37;
  --font-display: Cinzel, 'Trajan Pro', Georgia, serif;
  --font-body: Jost, system-ui, sans-serif;
  --font-arabic: 'Amiri Quran', 'Scheherazade New', serif;
  color-scheme: dark;
}

html,
body {
  margin: 0;
  background: var(--color-background);
  color: var(--color-foreground);
  font-family: var(--font-body);
}

/* No scroll bar: it broke the dark scene. Scrolling works the same without it. */
html {
  scrollbar-width: none;
}

html::-webkit-scrollbar {
  display: none;
}

/* A tall section; the stage inside it stays pinned while it scrolls past. Its height is one screen
   plus the timeline in main.js (4.1 screens): the rest, the opening, then one group of aayat, before
   the page moves on. Phones scroll two thirds as far, because a finger moves further per swipe than
   a mouse wheel per click. */
.hero {
  position: relative;
  height: 510vh;
}

.stage {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh; /* the book stays whole behind mobile browser bars */
  overflow: hidden;
}

/* The book and its aayat sit together in .subject, which atmosphere.js moves slightly while nobody is
   scrolling. The light in the air is a second canvas over everything, and never catches clicks. */
.subject,
.air {
  position: absolute;
  inset: 0;
}

.subject canvas,
.air {
  display: block;
  width: 100%;
  height: 100%;
}

.air {
  pointer-events: none;
}

/* The headline, centred in the space under the closed book. --book-h is the book's height on screen,
   set by main.js, which also fades it out as the cover starts to open. */
.wordmark {
  position: absolute;
  z-index: 1; /* over .subject: the frame's feathered bottom edge reaches the headline on some screens */
  left: 0;
  right: 0;
  bottom: calc((50% - var(--book-h, 60svh) / 2) / 2);
  transform: translateY(50%);
  padding: 0 1.5rem;
  text-align: center;
}

.wordmark h1 {
  margin: 0;
  padding-left: 0.2em; /* balances the letter-spacing after the last letter, so the text sits truly centred */
  font-family: var(--font-display);
  font-size: clamp(1.125rem, 0.9rem + 1vw, 1.625rem);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.wordmark p {
  margin: 0.7em 0 0;
  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
  font-weight: 300;
  letter-spacing: 0.06em;
  color: var(--color-muted-foreground);
}

/* Aayat, laid over the open book's pages. The numbers are page positions in the 1280x720 footage:
   left page x 262-636, right page x 645-1020, both y 80-640. main.js sets --s (the book's scale) and
   --x0/--y0 (where the footage's corner sits once the book is open), and each group's opacity. */
.aayat {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.group {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 600ms cubic-bezier(0.32, 0.72, 0, 1); /* main.js only switches opacity between 0 and 1 */
  mix-blend-mode: multiply; /* the ink sits in the paper, so the paper's shading shows through it */
}

.page {
  position: absolute;
  top: calc(var(--y0, 0px) + 80px * var(--s, 1));
  width: calc(375px * var(--s, 1));
  height: calc(560px * var(--s, 1));
  padding: calc(56px * var(--s, 1)) calc(40px * var(--s, 1));
  display: flex;
  flex-direction: column;
  justify-content: safe center;
  gap: 1.25em;
  overflow: hidden;
  text-align: center;
  color: #2B211B; /* dark ink, 14:1 on the cream page */
}

.page p {
  margin: 0;
}

.page.right {
  left: calc(var(--x0, 0px) + 645px * var(--s, 1));
  font-size: calc(30px * var(--s, 1));
}

.page.left {
  left: calc(var(--x0, 0px) + 262px * var(--s, 1));
  font-size: calc(16px * var(--s, 1));
}

.arabic {
  font-family: var(--font-arabic);
  line-height: 2.2; /* room for the marks above and below the letters */
}

.marker {
  color: #A16207; /* gold only for the small accents */
}

.surah {
  padding-left: 0.15em;
  font-family: var(--font-display);
  font-size: 1.2em;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #8A6A1F;
}

.meaning {
  display: none;
  font-weight: 400;
  line-height: 1.6;
  color: #3A302A;
}

.ref {
  font-size: 0.85em;
  letter-spacing: 0.08em;
  color: #6B5E55;
}

@media (max-width: 767px) {
  .hero {
    height: 373vh; /* one screen plus two thirds of 4.1 */
  }

  /* The pages are too small for a second block of text, so the left page's text sits under the book. */
  .group {
    mix-blend-mode: normal;
  }

  .page.left {
    left: 1.5rem;
    right: 1.5rem;
    width: auto;
    top: calc(var(--y0, 0px) + 650px * var(--s, 1) + 1rem);
    height: calc(var(--y0, 0px) + 70px * var(--s, 1) - 2rem);
    padding: 0;
    font-size: 0.875rem;
    color: var(--color-muted-foreground);
  }

  .page.left .surah {
    color: var(--color-accent);
  }

  .page.left .meaning,
  .page.left .ref {
    color: var(--color-muted-foreground);
  }
}

/* Reduced motion: no scrubbing, just the open book with a random group of aayat. */
.still .hero {
  height: auto;
}

.still .group {
  transition: none;
}

/* TRYOUT: phase 3 options, set on <html> by main.js. Once the user picks, move the picks above and
   delete everything below. */
[data-arabic='scheherazade'] {
  --font-arabic: 'Scheherazade New', 'Amiri Quran', serif;
}

[data-left='meaning'] .meaning {
  display: block;
}

/* Phase 4, "Aayat while moving: Fix B" (set by atmosphere.js): plain ink, as on phones. */
[data-ink='flat'] .group {
  mix-blend-mode: normal;
}

.tryout input[type='range'] {
  width: 10em;
  accent-color: #d4af37;
}

.tryout output {
  min-width: 7em;
  font-variant-numeric: tabular-nums;
}

.tryout {
  position: fixed;
  right: 12px; /* bottom-right, clear of the headline picker (wordmark-options.js) in the bottom-left */
  bottom: 12px;
  max-width: calc(100vw - 24px);
  max-height: calc(100svh - 24px); /* scrolls inside itself on a phone */
  overflow-y: auto;
  padding: 10px 12px;
  border: 1px solid #3F3A37;
  border-radius: 12px;
  background: rgba(0, 0, 0, 0.7);
  font: 13px/1 system-ui, sans-serif;
  color: #e7e0d8;
}

.tryout .readout {
  max-width: 34em;
  margin: 10px 0 2px;
  line-height: 1.4;
  color: #A8A29E;
  font-variant-numeric: tabular-nums;
}

.tryout summary {
  padding: 4px 0;
  cursor: pointer;
}

.tryout div {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
}

.tryout span {
  min-width: 10em;
  color: #A8A29E;
}

.tryout button {
  padding: 10px 14px;
  border: 1px solid #5c5048;
  border-radius: 999px;
  background: transparent;
  color: #e7e0d8;
  font: inherit;
  cursor: pointer;
}

.tryout button[aria-pressed='true'] {
  border-color: #d4af37;
  color: #d4af37;
}

/* TRYOUT, phones only: how far to scroll through the hero, and where the surah name goes. */
@media (max-width: 767px) {
  [data-phone-scroll='medium']:not(.still) .hero {
    height: 310vh;
  }

  [data-phone-scroll='short']:not(.still) .hero {
    height: 250vh;
  }

  [data-phone-left='page'] .page.left {
    left: calc(var(--x0, 0px) + 262px * var(--s, 1));
    right: auto;
    top: calc(var(--y0, 0px) + 80px * var(--s, 1));
    width: calc(375px * var(--s, 1));
    height: calc(560px * var(--s, 1));
    padding: calc(56px * var(--s, 1)) calc(16px * var(--s, 1));
    font-size: max(9px, calc(16px * var(--s, 1)));
    color: #2B211B;
  }

  [data-phone-left='page'] .page.left .surah {
    color: #8A6A1F;
  }

  [data-phone-left='page'] .page.left .ref {
    color: #6B5E55;
  }

  [data-phone-left='page'] .page.left .meaning {
    display: none; /* too long for a page this small */
  }
}

content.content:
1	// Phase 1: the hero scroll animation. Phase 2: the headline with the closed book. Phase 3: aayat on the open pages.
2	// Retouched video frames of the Qur'an opening, drawn to a canvas by scroll position.
3	// Spec: WEBSITE-BUILD.md sections 2 to 4; the settings the user chose are under section 7.
4	
5	(() => {
6	  const clamp = (v) => Math.min(1, Math.max(0, v));
7	  const smoothstep = (t) => t * t * (3 - 2 * t);
8	
9	  // Frames --------------------------------------------------------------------
10	
11	  const SKIP = [39, 40]; // identical to f038, a hold in the source video
12	  const urls = [];
13	  for (let i = 0; i <= 88; i++) {
14	    if (!SKIP.includes(i)) urls.push(`assets/hero/frames/f${String(i).padStart(3, '0')}.png`);
15	  }
16	  const LAST = urls.length - 1; // 87 frames, indices 0..86
17	
18	  // Geometry, in pixels of the 1280x720 frames ----------------------------------
19	
20	  const SRC_W = 1280;
21	  const SRC_H = 720;
22	  const BOOK_LEFT = 255;   // left edge of the book; it never moves in the footage
23	  const BOOK_H = 580;      // y 70-650, centred on the frame's middle
24	  const SPINE = 640;       // right edge until the cover passes upright
25	  const OPEN_RIGHT = 1037; // right edge fully open
26	  const FEATHER_X = 180;   // how far the frame's rectangle fades into the stage
27	  const FEATHER_Y = 40;
28	
29	  // Timeline, in screen heights of scrolling on a computer -----------------------
30	  // Phones scroll two thirds as far for everything (the hero is shorter there, in styles.css).
31	
32	  const REST = 0.45;  // closed book with the headline
33	  const OPEN = 2.25;  // the cover opens (the same scrolling as when the user signed off phase 1)
34	  const SETTLE = 0.4; // open pages
35	  const AYAH = 1;     // time to read the aayat before the page moves on
36	  const TOTAL = REST + OPEN + SETTLE + AYAH; // 4.1; .hero in styles.css is one screen taller than this
37	  const NAME_GONE = 8; // the headline has faded out by this frame, early in the opening
38	
39	  // Smoothing ---------------------------------------------------------------------
40	
41	  // A mouse wheel scrolls in steps, so everything glides toward the scroll position instead of
42	  // jumping to it, and the book cross-fades between frames. The user chose this "slow glide" by eye.
43	  let glide = 0.28; // roughly the seconds it takes to close two thirds of the gap; 0 jumps straight there
44	  let blend = true; // cross-fade neighbouring frames, rather than showing whole frames only
45	  // Stopped between two frames, the cross-fade settles onto the nearer frame over this many seconds: held still, it looks blurred.
46	  const SHARPEN = 0.25;
47	  // Once scrolling reaches this, the aayat fade in by themselves (the transition on .group), not with the scroll.
48	  const APPEAR = REST + OPEN * 0.9;
49	
50	  // A book left half open opens or closes by itself once scrolling stops: toward the nearer end, or the way the
51	  // visitor was scrolling. 'off' leaves it where it stopped.
52	  let finish = 'direction';
53	  let finishSpeed = 1;     // screens of scrolling a second; a half-open book is about one screen from either end
54	  const FINISH_WAIT = 180; // ms without scrolling before it finishes
55	
56	  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
57	  const hero = document.querySelector('.hero');
58	  const stage = hero.querySelector('.stage');
59	  const subject = stage.querySelector('.subject'); // the book and its aayat, moved together by atmosphere.js
60	  const canvas = subject.querySelector('canvas');
61	  const wordmark = stage.querySelector('.wordmark');
62	  const ctx = canvas.getContext('2d');
63	
64	  const frames = []; // decoded images by index, filled in as they arrive
65	  const rights = []; // measured right edge of the book in each frame
66	  const started = new Set();
67	  const groups = []; // one element per group of aayat, filled in when aayat.json arrives
68	
69	  let scale = 1;      // footage pixels to CSS pixels, set on resize
70	  let pos = null;     // scroll position shown, in screens; lags the real one while gliding
71	  let painted = null; // position last shown
72	  let drawn = null;   // frame last drawn; fractional between frames
73	  let last = 0;       // time of the previous glide step, 0 when at rest
74	  let dirty = true;
75	  let queued = false;
76	  let visible = true;
77	  let showing = false; // whether the pages show aayat
78	  let current = -1;   // the group of aayat last picked
79	  let previous = -1;  // the last group shown, so the next pass shows a different one
80	  let moving = false; // still gliding toward the scroll position; atmosphere.js keeps the book still meanwhile
81	  let sharpen = 1;    // 0 while moving, 1 once settled onto a whole frame
82	  let direction = 0;  // 1 when the visitor last scrolled down, -1 up
83	  let lastY = scrollY;
84	  let touching = false;
85	  let finishTimer = 0;
86	  let autoScroll = 0; // the animation frame of a scroll the page started itself, 0 when none
87	
88	  // Loading -----------------------------------------------------------------------
89	
90	  function load(i) {
91	    if (started.has(i)) return;
92	    started.add(i);
93	    const img = new Image();
94	    img.src = urls[i];
95	    img.decode().then(
96	      () => {
97	        frames[i] = img;
98	        rights[i] = measureRight(img);
99	        if (i >= LAST - 3) place(); // the open book's measured edge sets where the pages are
100	        dirty = true;
101	        schedule();
102	      },
103	      () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
104	    );
105	  }
106	
107	  // First and last frames, then coarse to fine, so scrubbing works before everything arrives.
108	  function loadAll() {
109	    load(0);
110	    load(LAST);
111	    for (const step of [8, 4, 2, 1]) {
112	      for (let i = 0; i <= LAST; i += step) load(i);
113	    }
114	  }
115	
116	  // Once the cover passes upright its cream lining faces the camera, so the book's right
117	  // edge is the rightmost bright pixel along the middle row, and never less than the spine.
118	  const probe = document.createElement('canvas');
119	  probe.width = SRC_W;
120	  probe.height = 1;
121	  const probeCtx = probe.getContext('2d', { willReadFrequently: true });
122	
123	  function measureRight(img) {
124	    try {
125	      probeCtx.drawImage(img, 0, SRC_H / 2, SRC_W, 1, 0, 0, SRC_W, 1);
126	      const px = probeCtx.getImageData(0, 0, SRC_W, 1).data;
127	      for (let x = SRC_W - 1; x > SPINE; x--) {
128	        if (px[x * 4] + px[x * 4 + 1] + px[x * 4 + 2] > 300) return x + 1;
129	      }
130	      return SPINE;
131	    } catch {
132	      return null; // pixels unreadable, e.g. opened as a file rather than through serve.js
133	    }
134	  }
135	
136	  // Averaged over nearby frames so the centring glides instead of stepping.
137	  function rightEdge(i) {
138	    let sum = 0;
139	    let n = 0;
140	    for (let j = Math.max(0, i - 3); j <= Math.min(LAST, i + 3); j++) {
141	      if (rights[j] != null) {
142	        sum += rights[j];
143	        n++;
144	      }
145	    }
146	    return n ? sum / n : SPINE + ((OPEN_RIGHT - SPINE) * i) / LAST;
147	  }
148	
149	  // Aayat -------------------------------------------------------------------------
150	  // The exact text comes from aayat.json, written by fetch-aayat.js from Quran.com. Never typed by hand.
151	
152	  const aayat = document.createElement('div');
153	  aayat.className = 'aayat';
154	  subject.append(aayat);
155	
156	  function el(tag, className, text) {
157	    const node = document.createElement(tag);
158	    node.className = className;
159	    if (text) node.textContent = text;
160	    return node;
161	  }
162	
163	  // Arabic on the right page, the first page in a mushaf, each ayah closed by its numbered marker.
164	  // The left page carries the surah name, reference and English meaning.
165	  function renderGroup({ ref, surah, aayat: verses }) {
166	    const group = el('section', 'group');
167	    const right = el('div', 'page right');
168	    const arabic = el('p', 'arabic');
169	    arabic.lang = 'ar';
170	    arabic.dir = 'rtl';
171	    for (const { key, text } of verses) {
172	      const marker = el('span', 'marker', `۝${Number(key.split(':')[1]).toLocaleString('ar-u-nu-arab')}`);
173	      marker.setAttribute('aria-hidden', 'true');
174	      arabic.append(`${text} `, marker, ' ');
175	    }
176	    right.append(arabic);
177	    const left = el('div', 'page left');
178	    left.append(
179	      el('p', 'surah', surah),
180	      el('p', 'meaning', verses.map((v) => v.translation).join(' ')),
181	      el('p', 'ref', ref.replace('-', '–')),
182	    );
183	    group.append(right, left);
184	    return group;
185	  }
186	
187	  fetch('aayat.json')
188	    .then((res) => res.json())
189	    .then((data) => {
190	      for (const g of data.groups) groups.push(aayat.appendChild(renderGroup(g)));
191	      fit();
192	      dirty = true;
193	      schedule();
194	    })
195	    .catch(() => console.warn('No aayat yet: run fetch-aayat.js'));
196	
197	  // Where the open book's pages are: CSS lays the text over them from these.
198	  function place() {
199	    const open = (BOOK_LEFT + rightEdge(LAST)) / 2;
200	    stage.style.setProperty('--s', scale);
201	    stage.style.setProperty('--x0', `${canvas.clientWidth / 2 - open * scale}px`);
202	    stage.style.setProperty('--y0', `${(canvas.clientHeight - SRC_H * scale) / 2}px`);
203	    stage.style.setProperty('--book-h', `${BOOK_H * scale}px`);
204	  }
205	
206	  // Shrinks a page's text until it fits, for aayat longer than the page holds at its normal size.
207	  function fit() {
208	    for (const page of aayat.querySelectorAll('.page')) {
209	      page.style.fontSize = '';
210	      let size = parseFloat(getComputedStyle(page).fontSize);
211	      while (page.scrollHeight > page.clientHeight && size > 10) {
212	        size *= 0.94;
213	        page.style.fontSize = `${size}px`;
214	      }
215	    }
216	  }
217	
218	  // One group at a time, picked at random each time the pages come into view. It fades in by itself once
219	  // the book is open and stays; scrolling back before that fades it out, so the next pass picks again.
220	  // Under reduced motion a random group is simply shown.
221	  function showAayat(s, still) {
222	    const show = still || s >= APPEAR;
223	    if (show === showing || !groups.length) return;
224	    showing = show;
225	    if (show) current = pick();
226	    groups.forEach((group, k) => {
227	      group.style.opacity = show && k === current ? 1 : 0;
228	    });
229	  }
230	
231	  // A random group, never the one shown last time.
232	  function pick() {
233	    let k;
234	    do k = Math.floor(Math.random() * groups.length);
235	    while (groups.length > 1 && k === previous);
236	    return (previous = k);
237	  }
238	
239	  // Drawing -----------------------------------------------------------------------
240	
241	  // Cross-fades the two frames either side of a position, or while they are still loading, draws
242	  // the nearest frame that has arrived. Returns false while no frame has loaded yet.
243	  function draw(at) {
244	    const a = Math.floor(at);
245	    const b = Math.min(a + 1, LAST);
246	    const f = at - a;
247	    const fade = f > 0 && !!frames[a] && !!frames[b];
248	    const base = fade ? a : nearestLoaded(Math.round(at));
249	    if (base < 0) return false;
250	
251	    const width = canvas.clientWidth;
252	    const height = canvas.clientHeight;
253	    // The book is centred by choosing which part of the frame is drawn, never by moving the canvas.
254	    const right = rightEdge(a) + (rightEdge(b) - rightEdge(a)) * f;
255	    const centre = (BOOK_LEFT + right) / 2;
256	    const w = SRC_W * scale;
257	    const h = SRC_H * scale;
258	    const x = width / 2 - centre * scale;
259	    const y = (height - h) / 2;
260	
261	    ctx.globalCompositeOperation = 'source-over';
262	    ctx.clearRect(0, 0, width, height);
263	    ctx.drawImage(frames[base], x, y, w, h);
264	    if (fade) {
265	      ctx.globalAlpha = f;
266	      ctx.drawImage(frames[b], x, y, w, h);
267	      ctx.globalAlpha = 1;
268	    }
269	    featherEdges(x, y, w, h);
270	
271	    // Where the book is on screen, so atmosphere.js keeps its dust and light off it.
272	    const top = y + ((SRC_H - BOOK_H) / 2) * scale;
273	    hero.book = { left: x + BOOK_LEFT * scale, right: x + right * scale, top, bottom: top + BOOK_H * scale, scale };
274	    return true;
275	  }
276	
277	  // Fades a drawn rectangle out at its edges so it never shows against the stage.
278	  function featherEdges(x, y, w, h) {
279	    ctx.globalCompositeOperation = 'destination-in';
280	    ctx.fillStyle = feather(ctx.createLinearGradient(x, 0, x + w, 0), FEATHER_X / SRC_W);
281	    ctx.fillRect(x, y, w, h);
282	    ctx.fillStyle = feather(ctx.createLinearGradient(0, y, 0, y + h), FEATHER_Y / SRC_H);
283	    ctx.fillRect(x, y, w, h);
284	    ctx.globalCompositeOperation = 'source-over';
285	  }
286	
287	  function feather(gradient, edge) {
288	    gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
289	    gradient.addColorStop(edge, '#000');
290	    gradient.addColorStop(1 - edge, '#000');
291	    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
292	    return gradient;
293	  }
294	
295	  // How far the hero has been scrolled, in computer screen heights (0 to TOTAL).
296	  function targetScroll() {
297	    const range = hero.offsetHeight - stage.offsetHeight;
298	    return range > 0 ? clamp(-hero.getBoundingClientRect().top / range) * TOTAL : 0;
299	  }
300	
301	  // The book's frame at a scroll position; smoothstep eases into and out of the opening.
302	  function frameAt(s) {
303	    return smoothstep(clamp((s - REST) / OPEN)) * LAST;
304	  }
305	
306	  function nearestLoaded(i) {
307	    for (let d = 0; d <= LAST; d++) {
308	      if (frames[i - d]) return i - d;
309	      if (frames[i + d]) return i + d;
310	    }
311	    return -1;
312	  }
313	
314	  function schedule() {
315	    if (queued) return;
316	    queued = true;
317	    requestAnimationFrame(step);
318	  }
319	
320	  // Each animation frame, moves part of the way toward the scroll position and keeps going until it arrives,
321	  // then settles onto a whole frame. Uses elapsed time, so it feels the same on 60 Hz and 144 Hz screens.
322	  function step(now) {
323	    queued = false;
324	    if (!visible) {
325	      last = 0;
326	      return;
327	    }
328	    const target = targetScroll();
329	    const dt = last ? Math.min(now - last, 50) / 1000 : 1 / 60;
330	    if (pos === null || reduceMotion.matches || !glide) {
331	      pos = target;
332	    } else {
333	      pos += (target - pos) * (1 - Math.exp(-dt / glide));
334	      if (Math.abs(target - pos) < 0.0005) pos = target;
335	    }
336	    sharpen = pos === target ? Math.min(1, sharpen + dt / SHARPEN) : Math.max(0, sharpen - (3 * dt) / SHARPEN);
337	    last = pos === target && sharpen === 1 ? 0 : now;
338	    paint();
339	    if (moving !== (pos !== target)) {
340	      moving = pos !== target;
341	      hero.dispatchEvent(new Event(moving ? 'bookmove' : 'bookrest'));
342	    }
343	    if (last) schedule();
344	  }
345	
346	  // Updates the headline and aayat, and redraws the book only when its frame, the size or the loaded
347	  // frames have changed. Under reduced motion the book is shown open and the headline stays.
348	  function paint() {
349	    if (pos === null) return;
350	    const still = reduceMotion.matches;
351	    const exact = frameAt(pos);
352	    const whole = Math.round(exact);
353	    const frame = still ? LAST : blend ? exact + (whole - exact) * smoothstep(sharpen) : whole;
354	    if (pos !== painted || dirty) {
355	      wordmark.style.opacity = still ? 1 : 1 - clamp(frame / NAME_GONE);
356	      showAayat(pos, still);
357	      painted = pos;
358	    }
359	    if (frame !== drawn || dirty) {
360	      if (draw(frame)) {
361	        drawn = frame;
362	        dirty = false;
363	      }
364	    }
365	  }
366	
367	  function resize() {
368	    const width = canvas.clientWidth;
369	    const height = canvas.clientHeight;
370	    const dpr = Math.min(devicePixelRatio || 1, 2);
371	    canvas.width = Math.round(width * dpr);
372	    canvas.height = Math.round(height * dpr);
373	    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
374	    ctx.imageSmoothingQuality = 'high';
375	    // One size for the whole opening: the open book always fits, and the 720p footage is
376	    // never stretched past its own size.
377	    scale = Math.min((height * 0.8) / BOOK_H, (width * 0.88) / (OPEN_RIGHT - BOOK_LEFT), 1);
378	    place();
379	    fit();
380	    dirty = true;
381	    paint(); // draw now: resizing the canvas has just cleared it
382	    schedule(); // the hero's height follows the window, so the scroll position may now mean a different frame
383	  }
384	
385	  // Reduced motion: no scrubbing, just the open book, and only its frame is loaded.
386	  function applyMotion() {
387	    document.documentElement.classList.toggle('still', reduceMotion.matches);
388	    if (reduceMotion.matches) load(LAST);
389	    else loadAll();
390	    dirty = true;
391	    schedule();
392	  }
393	
394	  // TRYOUT --------------------------------------------------------------------------
395	  // Options shown only on this PC or a phone on the same wifi. Once the user picks: put the picks in the
396	  // settings above and in styles.css, then delete this block, the TRYOUT part of styles.css and the
397	  // unused Arabic font in index.html.
398	
399	  if (/^(localhost|[\d.]+)$/.test(location.hostname)) {
400	    const narrow = matchMedia('(max-width: 767px)').matches;
401	    const panel = document.createElement('details');
402	    panel.className = 'tryout';
403	    panel.open = !narrow; // closed to start with on phones, where it would cover the book
404	    panel.innerHTML = '<summary>Options</summary>';
405	    document.body.append(panel);
406	
407	    // A row of buttons; the one matching `initial` starts pressed. atmosphere.js adds its rows with this too.
408	    window.addOption = (label, choices, initial, pick) => {
409	      const row = document.createElement('div');
410	      row.append(el('span', '', label));
411	      for (const [text, value] of Object.entries(choices)) {
412	        const b = el('button', '', text);
413	        b.type = 'button';
414	        b.setAttribute('aria-pressed', value === initial);
415	        b.addEventListener('click', () => {
416	          for (const other of row.querySelectorAll('button')) other.setAttribute('aria-pressed', other === b);
417	          pick(value);
418	        });
419	        row.append(b);
420	      }
421	      panel.append(row);
422	    };
423	
424	    // A slider with its value shown beside it, in the words `format` gives.
425	    window.addSlider = (label, min, max, step, initial, format, pick) => {
426	      const row = document.createElement('div');
427	      const range = el('input', '');
428	      Object.assign(range, { type: 'range', min, max, step, value: initial });
429	      range.setAttribute('aria-label', label);
430	      const shown = el('output', '', format(initial));
431	      range.addEventListener('input', () => {
432	        const value = Number(range.value);
433	        shown.textContent = format(value);
434	        pick(value);
435	      });
436	      row.append(el('span', '', label), range, shown);
437	      panel.append(row);
438	    };
439	
440	    const redraw = () => {
441	      dirty = true;
442	      schedule();
443	    };
444	    const retime = (set) => (value) => {
445	      set(value);
446	      redraw();
447	    };
448	    const setData = (key) => (value) => {
449	      document.documentElement.dataset[key] = value;
450	      fit();
451	    };
452	    const glideText = (v) => (v ? `${v.toFixed(2)} s${v === 0.28 ? ' (your pick)' : ''}` : 'Off');
453	    addSlider('Opening glide', 0, 0.5, 0.01, glide, glideText, retime((v) => (glide = v)));
454	    addOption('Blend frames', { Off: false, On: true }, blend, retime((v) => (blend = v)));
455	    addOption('Half-open book', { Stays: 'off', 'Nearer end': 'nearest', 'Way you scrolled': 'direction' }, finish, (v) => (finish = v));
456	    addSlider('Auto open/close speed', 25, 300, 5, finishSpeed * 100, (v) => `${v}%`, (v) => (finishSpeed = v / 100));
457	    addOption('Arabic lettering', { 'Amiri Quran': 'amiri', Scheherazade: 'scheherazade' }, 'amiri', setData('arabic'));
458	    addOption('Left page', { 'Surah name': 'name', 'English meaning': 'meaning' }, 'name', setData('left'));
459	    if (narrow) {
460	      const phoneScroll = setData('phoneScroll');
461	      phoneScroll('short');
462	      addOption('Scroll length', { Long: 'long', Medium: 'medium', Short: 'short' }, 'short', (v) => {
463	        phoneScroll(v);
464	        redraw();
465	      });
466	      addOption('Surah name', { 'Under the book': 'under', 'On the page': 'page' }, 'under', setData('phoneLeft'));
467	    }
468	  }
469	
470	  // Finishing the opening ------------------------------------------------------------
471	
472	  function onScroll() {
473	    schedule();
474	    if (autoScroll) return; // the page's own scrolling
475	    direction = Math.sign(scrollY - lastY) || direction;
476	    lastY = scrollY;
477	    waitToFinish();
478	  }
479	
480	  function waitToFinish() {
481	    clearTimeout(finishTimer);
482	    finishTimer = setTimeout(finishOpening, FINISH_WAIT);
483	  }
484	
485	  function finishOpening() {
486	    if (finish === 'off' || touching || autoScroll || reduceMotion.matches || !visible) return;
487	    const progress = (targetScroll() - REST) / OPEN;
488	    if (progress <= 0.002 || progress >= 0.998) return; // closed or open already
489	    const open = finish === 'nearest' ? progress >= 0.5 : direction > 0;
490	    scrollToScreens(open ? REST + OPEN : REST);
491	  }
492	
493	  // Scrolls the page to a point on the hero's timeline, easing in and out.
494	  function scrollToScreens(s) {
495	    const range = hero.offsetHeight - stage.offsetHeight;
496	    const from = scrollY;
497	    const distance = hero.getBoundingClientRect().top + scrollY + (s / TOTAL) * range - from;
498	    const duration = Math.max(300, (1000 * Math.abs(distance)) / innerHeight / finishSpeed); // a short finish still eases
499	    const start = performance.now();
500	    const tick = (now) => {
501	      const t = Math.min(1, (now - start) / duration);
502	      const eased = t < 0.5 ? 4 * t * t * t : 1 - (2 - 2 * t) ** 3 / 2;
503	      scrollTo(0, from + distance * eased);
504	      autoScroll = t < 1 ? requestAnimationFrame(tick) : 0;
505	      if (!autoScroll) lastY = scrollY;
506	    };
507	    autoScroll = requestAnimationFrame(tick);
508	  }
509	
510	  // Any scrolling by the visitor takes over from the page's own.
511	  function takeOver() {
512	    cancelAnimationFrame(autoScroll);
513	    autoScroll = 0;
514	    lastY = scrollY;
515	  }
516	
517	  addEventListener('scroll', onScroll, { passive: true });
518	  for (const type of ['wheel', 'keydown', 'mousedown']) addEventListener(type, takeOver, { passive: true });
519	  addEventListener(
520	    'touchstart',
521	    () => {
522	      touching = true;
523	      takeOver();
524	    },
525	    { passive: true },
526	  );
527	  addEventListener(
528	    'touchend',
529	    () => {
530	      touching = false;
531	      waitToFinish();
532	    },
533	    { passive: true },
534	  );
535	  document.fonts.addEventListener('loadingdone', fit); // text changes size when its font arrives
536	  reduceMotion.addEventListener('change', applyMotion);
537	  new ResizeObserver(resize).observe(canvas);
538	  new IntersectionObserver(([entry]) => {
539	    visible = entry.isIntersecting;
540	    dirty = true;
541	    schedule();
542	  }).observe(hero);
543	  applyMotion();
544	})();
