1	// Phase 4: atmosphere, dark theme only for now (light mode is phase 6). Around the book: gold dust, gold leaf and
2	// glints mixed by amount, drifting haze, a warm light behind the book, and a gold geometric pattern (faint, or shown
3	// only under the mouse), with a soft glow that follows the mouse. The book (with its aayat) moves slightly while
4	// nobody is scrolling.
5	// Spec: WEBSITE-BUILD.md sections 5 and 7. Nothing is ever drawn over the Qur'an itself: the book's area, which
6	// main.js reports as hero.book, is erased from this layer every frame. All of it is decoration: it stops offscreen
7	// and under reduced motion, and lightens itself, then switches off, on devices that measurably can't keep up.
8	
9	(() => {
10	  const TAU = Math.PI * 2;
11	  const wave = (t, period, phase = 0) => Math.sin((t / period) * TAU + phase);
12	  const ease = (value, target, seconds, dt) => value + (target - value) * (1 - Math.exp(-dt / seconds));
13	  const rand = (min, max) => min + Math.random() * (max - min);
14	  const wrap = (v, size) => (v < -20 ? v + size + 40 : v > size + 20 ? v - size - 40 : v);
15	
16	  const root = document.documentElement;
17	  const hero = document.querySelector('.hero');
18	  const stage = hero.querySelector('.stage');
19	  const subject = stage.querySelector('.subject');
20	  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
21	  const mouse = matchMedia('(hover: hover) and (pointer: fine)');
22	
23	  // Starting choices, until the user picks from the options panel. Amounts are percentages, 0 for none; glow is the
24	  // glow's radius in CSS pixels.
25	  const settings = { dust: 100, leaf: 40, glints: 0, haze: 30, halo: 40, pattern: 'off', glow: 90, idle: 'drift', move: 100, text: 'steady' };
26	  const IDLE_DELAY = 600;    // ms the book must have stopped before it starts moving by itself
27	  const MAX_PARTICLES = 400; // of each kind
28	  const LENS = 150;          // radius, in CSS pixels, of the patch of pattern the mouse uncovers
29	
30	  // Clear space kept around the book, in footage pixels, scaled with the book. The open pages reach a little past
31	  // the measured rectangle at the bottom right, and the book moves slightly while still.
32	  const CLEAR = { top: 20, side: 16, bottom: 44, feather: 40 };
33	
34	  // Smoothness is judged in two-second windows, only while the book is still and the tab is showing: while
35	  // scrolling, the book's frames cost more than the atmosphere, and a hidden tab pauses. Three slow windows in a
36	  // row lighten the effects; three more switch them off. Choosing any effect option turns them back on.
37	  const WINDOW = 2000; // ms
38	  const MIN_FPS = 45;
39	  const BAD_WINDOWS = 3;
40	  const WARMUP = 4000; // ms after load before judging, while the book's frames are still decoding
41	
42	  const canvas = document.createElement('canvas');
43	  canvas.className = 'air';
44	  canvas.setAttribute('aria-hidden', 'true');
45	  stage.append(canvas);
46	  const ctx = canvas.getContext('2d');
47	  const lens = document.createElement('canvas'); // the pattern under the mouse is cut out here, then stamped
48	  const lensCtx = lens.getContext('2d');
49	
50	  const pointer = { x: 0, y: 0, inside: false };             // the mouse, in window pixels
51	  const lamp = { x: 0, y: 0, r: settings.glow, strength: 0 }; // trails the mouse; the glow and pattern follow it
52	  const particles = { dust: [], leaf: [], glints: [] };
53	
54	  let width = 0;
55	  let height = 0;
56	  let dpr = 1;
57	  let unit = 1;               // screen height / 900, so things look the same size on a phone and a computer
58	  let presence = 0;           // fades everything in when it (re)starts
59	  let inked = false;          // something was drawn last frame, so the canvas needs clearing
60	  let idle = 0;               // 0 while the book moves with the scroll, 1 once it has been still a while
61	  let motion = settings.idle; // the last movement chosen, so switching it off eases out
62	  let bookTransform = '';
63	  let bookLayer = false;      // whether .subject has will-change: transform
64	  let gliding = false;        // main.js is still moving the book toward the scroll position
65	  let lastMove = -Infinity;
66	  let level = 'full';         // full, lite or off
67	  let visible = true;
68	  let raf = 0;
69	  let last = 0;
70	  let windowStart = 0;
71	  let frames = 0;
72	  let badWindows = 0;
73	  let starPattern = null;     // the gold pattern, rebuilt for each screen size
74	  let lensPattern = null;
75	
76	  // Sprites: shapes drawn once, then stamped, so each frame is mostly image copies -----------------------
77	
78	  function sprite(size, paint) {
79	    const c = document.createElement('canvas');
80	    c.width = c.height = size;
81	    paint(c.getContext('2d'), size);
82	    return c;
83	  }
84	
85	  const radial = (stops) => (g, size) => {
86	    const r = size / 2;
87	    const gradient = g.createRadialGradient(r, r, 0, r, r, r);
88	    for (const [at, color] of stops) gradient.addColorStop(at, color);
89	    g.fillStyle = gradient;
90	    g.fillRect(0, 0, size, size);
91	  };
92	
93	  // Outlines of three torn flakes of gold leaf, in a 32 px square.
94	  const LEAF_SHAPES = [
95	    [[6, 9], [25, 4], [28, 21], [12, 28], [4, 20]],
96	    [[9, 5], [27, 11], [22, 27], [5, 24]],
97	    [[4, 12], [18, 3], [29, 15], [20, 29], [8, 26]],
98	  ];
99	
100	  const S = {
101	    speck: sprite(32, radial([[0, 'rgba(255,240,210,1)'], [0.3, 'rgba(240,210,150,0.5)'], [1, 'rgba(212,175,55,0)']])),
102	    soft: sprite(64, radial([[0, 'rgba(255,240,210,1)'], [0.55, 'rgba(240,210,150,0.5)'], [1, 'rgba(212,175,55,0)']])),
103	    glow: sprite(256, radial([[0, 'rgba(255,222,165,0.13)'], [0.4, 'rgba(255,215,150,0.05)'], [1, 'rgba(255,215,150,0)']])),
104	    halo: sprite(256, radial([[0, 'rgba(212,175,55,0.45)'], [0.45, 'rgba(212,175,55,0.16)'], [1, 'rgba(212,175,55,0)']])),
105	    fade: sprite(256, radial([[0, '#fff'], [0.5, 'rgba(255,255,255,0.6)'], [1, 'rgba(255,255,255,0)']])),
106	    // A four-pointed sparkle: a bright core with thin flares across and down.
107	    glint: sprite(48, (g, size) => {
108	      radial([[0, 'rgba(255,250,235,1)'], [0.1, 'rgba(255,230,170,0.85)'], [0.3, 'rgba(212,175,55,0.15)'], [1, 'rgba(212,175,55,0)']])(g, size);
109	      const c = size / 2;
110	      for (const across of [true, false]) {
111	        const flare = across ? g.createLinearGradient(0, 0, size, 0) : g.createLinearGradient(0, 0, 0, size);
112	        flare.addColorStop(0, 'rgba(255,245,220,0)');
113	        flare.addColorStop(0.5, 'rgba(255,245,220,0.9)');
114	        flare.addColorStop(1, 'rgba(255,245,220,0)');
115	        g.fillStyle = flare;
116	        if (across) g.fillRect(0, c - 1, size, 2);
117	        else g.fillRect(c - 1, 0, 2, size);
118	      }
119	    }),
120	    leaves: LEAF_SHAPES.map((shape) =>
121	      sprite(32, (g) => {
122	        const metal = g.createLinearGradient(4, 4, 28, 28);
123	        metal.addColorStop(0, '#7A5A12');
124	        metal.addColorStop(0.45, '#F3DE9A');
125	        metal.addColorStop(1, '#C9A962');
126	        g.fillStyle = metal;
127	        g.beginPath();
128	        for (const [x, y] of shape) g.lineTo(x, y);
129	        g.closePath();
130	        g.fill();
131	      }),
132	    ),
133	    haze: hazeTile(256),
134	  };
135	  const hazePattern = ctx.createPattern(S.haze, 'repeat');
136	
137	  // Soft, tileable wisps: four octaves of smooth random noise, keeping only the brighter parts.
138	  function hazeTile(size) {
139	    const c = document.createElement('canvas');
140	    c.width = c.height = size;
141	    const g = c.getContext('2d');
142	    const img = g.createImageData(size, size);
143	    const octaves = [4, 8, 16, 32].map((n) => ({ n, v: Float32Array.from({ length: n * n }, Math.random) }));
144	    for (let y = 0; y < size; y++) {
145	      for (let x = 0; x < size; x++) {
146	        let sum = 0;
147	        let amp = 1;
148	        let total = 0;
149	        for (const { n, v } of octaves) {
150	          const fx = (x / size) * n;
151	          const fy = (y / size) * n;
152	          const x0 = Math.floor(fx);
153	          const y0 = Math.floor(fy);
154	          const x1 = (x0 + 1) % n;
155	          const y1 = (y0 + 1) % n;
156	          let tx = fx - x0;
157	          let ty = fy - y0;
158	          tx = tx * tx * (3 - 2 * tx);
159	          ty = ty * ty * (3 - 2 * ty);
160	          const top = v[y0 * n + x0] + (v[y0 * n + x1] - v[y0 * n + x0]) * tx;
161	          const bottom = v[y1 * n + x0] + (v[y1 * n + x1] - v[y1 * n + x0]) * tx;
162	          sum += (top + (bottom - top) * ty) * amp;
163	          total += amp;
164	          amp /= 2;
165	        }
166	        const k = (y * size + x) * 4;
167	        img.data[k] = 222;
168	        img.data[k + 1] = 196;
169	        img.data[k + 2] = 150;
170	        img.data[k + 3] = 255 * Math.max(0, (sum / total - 0.42) / 0.58) ** 1.8;
171	      }
172	    }
173	    g.putImageData(img, 0, 0);
174	    return c;
175	  }
176	
177	  // An eight-pointed star in each tile, its points joined to the neighbouring stars by thin gold lines.
178	  function buildPattern() {
179	    const size = Math.round(96 * Math.max(unit, 0.75)); // CSS pixels
180	    const px = Math.max(8, Math.round(size * dpr));
181	    const tile = document.createElement('canvas');
182	    tile.width = tile.height = px;
183	    const g = tile.getContext('2d');
184	    g.scale(px / size, px / size);
185	    g.strokeStyle = 'rgba(212,175,55,1)';
186	    g.lineWidth = 1;
187	    const c = size / 2;
188	    const r = size * 0.3;
189	    for (const turn of [0, Math.PI / 4]) {
190	      g.beginPath();
191	      for (let k = 0; k < 4; k++) g.lineTo(c + r * Math.cos(turn + (k * Math.PI) / 2), c + r * Math.sin(turn + (k * Math.PI) / 2));
192	      g.closePath();
193	      g.stroke();
194	    }
195	    g.beginPath();
196	    g.moveTo(0, c);
197	    g.lineTo(c - r, c);
198	    g.moveTo(c + r, c);
199	    g.lineTo(size, c);
200	    g.moveTo(c, 0);
201	    g.lineTo(c, c - r);
202	    g.moveTo(c, c + r);
203	    g.lineTo(c, size);
204	    g.stroke();
205	    starPattern = ctx.createPattern(tile, 'repeat');
206	    starPattern.setTransform(new DOMMatrix([size / px, 0, 0, size / px, 0, 0])); // the tile is in device pixels
207	    lensPattern = lensCtx.createPattern(tile, 'repeat');
208	  }
209	
210	  function stamp(image, x, y, r, alpha) {
211	    ctx.globalAlpha = alpha * presence;
212	    ctx.drawImage(image, x - r, y - r, r * 2, r * 2);
213	  }
214	
215	  // Gold in the air -----------------------------------------------------------------------------------
216	  // Base counts are for a 1440x900 screen at 100%, and scale with the screen's area and each kind's slider.
217	
218	  const KINDS = {
219	    // Fine gold dust on a slow current of air; now and then a speck turns and catches the light.
220	    dust: {
221	      base: 90,
222	      make(p) {
223	        const near = level === 'full' && Math.random() < 0.08;
224	        const depth = near ? rand(0.85, 1) : rand(0.1, 0.8);
225	        Object.assign(p, {
226	          x: rand(0, width),
227	          y: rand(0, height),
228	          near,
229	          depth,
230	          r: near ? rand(4, 8) : 0.9 + depth * 2.2,
231	          vx: 2 + depth * 6,
232	          vy: -(1 + depth * 3),
233	          sway: rand(4, 12),
234	          wander: rand(9, 20),
235	          twinkle: rand(3, 8),
236	          catches: !near && Math.random() < 0.35,
237	          catchEvery: rand(7, 16),
238	          phase: rand(0, TAU),
239	          alpha: near ? rand(0.05, 0.1) : 0.25 + depth * 0.5,
240	        });
241	      },
242	      draw(p, t, dt) {
243	        p.x = wrap(p.x + p.vx * unit * dt, width);
244	        p.y = wrap(p.y + p.vy * unit * dt, height);
245	        const x = p.x + wave(t, p.wander, p.phase) * p.sway * unit;
246	        const y = p.y + wave(t, p.wander * 1.3, p.phase) * p.sway * 0.5 * unit;
247	        const r = p.r * Math.max(unit, 0.8);
248	        stamp(p.near ? S.soft : S.speck, x, y, r, p.alpha * (0.75 + 0.25 * wave(t, p.twinkle, p.phase)));
249	        if (!p.catches) return;
250	        const shine = Math.max(0, wave(t, p.catchEvery, p.phase)) ** 30; // a slow swell, a few times a minute
251	        if (shine > 0.02) stamp(S.glint, x, y, (5 + 5 * p.depth) * unit * (0.5 + 0.5 * shine), shine * 0.9);
252	      },
253	    },
254	
255	    // Flakes of gold leaf falling slowly, turning over as they fall and flashing as they face the light.
256	    leaf: {
257	      base: 16,
258	      make(p, fresh) {
259	        const depth = rand(0.3, 1);
260	        Object.assign(p, {
261	          x: rand(0, width),
262	          y: fresh ? rand(0, height) : -20,
263	          leaf: Math.floor(rand(0, LEAF_SHAPES.length)),
264	          size: 5 + depth * 7,
265	          fall: 5 + depth * 9,
266	          sway: rand(15, 35),
267	          wander: rand(5, 9),
268	          angle: rand(0, TAU),
269	          spin: rand(-0.5, 0.5),
270	          flip: rand(0.8, 1.6),
271	          phase: rand(0, TAU),
272	          alpha: 0.5 + depth * 0.45,
273	        });
274	      },
275	      draw(p, t, dt) {
276	        p.y += p.fall * unit * dt;
277	        if (p.y > height + 20) this.make(p, false);
278	        p.angle += p.spin * dt;
279	        const x = p.x + wave(t, p.wander, p.phase) * p.sway * unit;
280	        const face = Math.cos(t * p.flip + p.phase); // 1 or -1 facing the viewer, 0 edge-on
281	        const s = p.size * unit;
282	        const cos = Math.cos(p.angle) * dpr;
283	        const sin = Math.sin(p.angle) * dpr;
284	        ctx.globalAlpha = p.alpha * presence * (0.35 + 0.65 * Math.abs(face));
285	        ctx.setTransform(cos, sin, -sin * face, cos * face, x * dpr, p.y * dpr);
286	        ctx.drawImage(S.leaves[p.leaf], -s / 2, -s / 2, s, s);
287	        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
288	        const shine = Math.max(0, face) ** 24;
289	        if (shine > 0.02) stamp(S.glint, x, p.y, s * 1.2, shine * 0.75);
290	      },
291	    },
292	
293	    // Sparkles that catch the light for a moment, then appear somewhere else.
294	    glints: {
295	      base: 24,
296	      make(p) {
297	        Object.assign(p, { r: rand(6, 13), period: rand(4, 10), offset: rand(0, 1), alpha: rand(0.55, 0.95), cycle: null });
298	      },
299	      draw(p, t) {
300	        const c = t / p.period + p.offset;
301	        const cycle = Math.floor(c);
302	        if (cycle !== p.cycle) {
303	          p.cycle = cycle;
304	          p.x = rand(0, width);
305	          p.y = rand(0, height);
306	        }
307	        const flash = Math.sin((c - cycle) * Math.PI) ** 24;
308	        if (flash > 0.01) stamp(S.glint, p.x, p.y, p.r * unit * (0.5 + 0.5 * flash), p.alpha * flash);
309	      },
310	    },
311	  };
312	
313	  // Makes the right number of one kind. A fresh start replaces them all; otherwise some are added or removed, so
314	  // dragging a slider doesn't restart the ones already there.
315	  function populate(kind, fresh = true) {
316	    const area = Math.min(1.5, Math.max(0.35, (width * height) / (1440 * 900)));
317	    let n = Math.round((KINDS[kind].base * area * settings[kind]) / 100);
318	    if (level === 'lite') n = Math.ceil(n / 2);
319	    n = Math.min(n, MAX_PARTICLES);
320	    const list = particles[kind];
321	    if (fresh) list.length = 0;
322	    list.length = Math.min(list.length, n);
323	    while (list.length < n) {
324	      const p = {};
325	      KINDS[kind].make(p, true);
326	      list.push(p);
327	    }
328	  }
329	
330	  // The background ---------------------------------------------------------------------------------------
331	
332	  // A warm light behind the book. Its middle is erased with the book, so it shows as a glow around the edges.
333	  function drawHalo(t) {
334	    const b = hero.book;
335	    if (!settings.halo || !b) return false;
336	    const r = Math.max(b.right - b.left, b.bottom - b.top) * (0.95 + 0.04 * wave(t, 11));
337	    ctx.globalAlpha = (settings.halo / 100) * presence;
338	    ctx.drawImage(S.halo, (b.left + b.right) / 2 - r, (b.top + b.bottom) / 2 - r, r * 2, r * 2);
339	    return true;
340	  }
341	
342	  // Two layers of haze drifting slowly in different directions. Left out at lite quality.
343	  const HAZE_LAYERS = [
344	    { scale: 6, vx: 5, vy: -1.5, alpha: 0.6 },
345	    { scale: 10, vx: -3, vy: -0.8, alpha: 0.4 },
346	  ];
347	
348	  function drawHaze(t) {
349	    if (!settings.haze || level === 'lite') return false;
350	    for (const layer of HAZE_LAYERS) {
351	      const k = layer.scale * unit;
352	      const span = S.haze.width * k;
353	      const x = (((t * layer.vx * unit) % span) + span) % span;
354	      const y = (((t * layer.vy * unit) % span) + span) % span;
355	      hazePattern.setTransform(new DOMMatrix([k, 0, 0, k, x, y]));
356	      ctx.fillStyle = hazePattern; // assigned after moving it: some browsers keep the transform from assignment
357	      ctx.globalAlpha = (settings.haze / 100) * layer.alpha * 0.5 * presence;
358	      ctx.fillRect(0, 0, width, height);
359	    }
360	    return true;
361	  }
362	
363	  function drawPattern() {
364	    if (settings.pattern !== 'faint') return false;
365	    ctx.globalAlpha = 0.07 * presence;
366	    ctx.fillStyle = starPattern;
367	    ctx.fillRect(0, 0, width, height);
368	    return true;
369	  }
370	
371	  // The mouse ------------------------------------------------------------------------------------------------
372	
373	  // Moves the lamp after the mouse with a slight lag, fading in and out. Returns whether it is showing.
374	  function trackLamp(dt) {
375	    const on = (settings.glow > 0 || settings.pattern === 'mouse') && pointer.inside && mouse.matches;
376	    if (settings.glow > 0) lamp.r = settings.glow;
377	    const snap = lamp.strength < 0.02; // appears where the mouse is, rather than sliding in from a corner
378	    lamp.strength = ease(lamp.strength, on ? 1 : 0, 0.35, dt);
379	    if (lamp.strength < 0.005) return false;
380	    const rect = canvas.getBoundingClientRect();
381	    const x = pointer.x - rect.left;
382	    const y = pointer.y - rect.top;
383	    lamp.x = snap ? x : ease(lamp.x, x, 0.08, dt);
384	    lamp.y = snap ? y : ease(lamp.y, y, 0.08, dt);
385	    return true;
386	  }
387	
388	  function drawGlow() {
389	    if (!settings.glow) return false;
390	    ctx.globalAlpha = lamp.strength;
391	    ctx.drawImage(S.glow, lamp.x - lamp.r, lamp.y - lamp.r, lamp.r * 2, lamp.r * 2);
392	    return true;
393	  }
394	
395	  // The pattern, uncovered in a soft circle under the mouse. It stays fixed to the page as the circle moves over it.
396	  function drawLens() {
397	    if (settings.pattern !== 'mouse') return false;
398	    const size = Math.round(LENS * 2 * dpr);
399	    if (lens.width !== size) lens.width = lens.height = size;
400	    lensCtx.globalCompositeOperation = 'source-over';
401	    lensCtx.clearRect(0, 0, size, size);
402	    lensPattern.setTransform(new DOMMatrix([1, 0, 0, 1, -(lamp.x - LENS) * dpr, -(lamp.y - LENS) * dpr]));
403	    lensCtx.fillStyle = lensPattern;
404	    lensCtx.fillRect(0, 0, size, size);
405	    lensCtx.globalCompositeOperation = 'destination-in';
406	    lensCtx.drawImage(S.fade, 0, 0, size, size);
407	    ctx.globalAlpha = 0.45 * lamp.strength;
408	    ctx.drawImage(lens, lamp.x - LENS, lamp.y - LENS, LENS * 2, LENS * 2);
409	    return true;
410	  }
411	
412	  // Erases this layer over the book, with a soft edge, so nothing ever sits on the Qur'an.
413	  function eraseBook() {
414	    const b = hero.book;
415	    if (!b) return;
416	    const s = b.scale;
417	    const f = CLEAR.feather * s;
418	    const l = b.left - CLEAR.side * s;
419	    const r = b.right + CLEAR.side * s;
420	    const t = b.top - CLEAR.top * s;
421	    const bottom = b.bottom + CLEAR.bottom * s;
422	    const w = r - l;
423	    const h = bottom - t;
424	    ctx.globalCompositeOperation = 'destination-out';
425	    ctx.globalAlpha = 1;
426	    ctx.fillStyle = '#000';
427	    ctx.fillRect(l, t, w, h);
428	    ctx.drawImage(MASK, 64, 0, 1, 64, l, t - f, w, f);     // top edge
429	    ctx.drawImage(MASK, 64, 64, 1, 64, l, bottom, w, f);   // bottom edge
430	    ctx.drawImage(MASK, 0, 64, 64, 1, l - f, t, f, h);     // left edge
431	    ctx.drawImage(MASK, 64, 64, 64, 1, r, t, f, h);        // right edge
432	    ctx.drawImage(MASK, 0, 0, 64, 64, l - f, t - f, f, f); // corners
433	    ctx.drawImage(MASK, 64, 0, 64, 64, r, t - f, f, f);
434	    ctx.drawImage(MASK, 0, 64, 64, 64, l - f, bottom, f, f);
435	    ctx.drawImage(MASK, 64, 64, 64, 64, r, bottom, f, f);
436	    ctx.globalCompositeOperation = 'source-over';
437	  }
438	
439	  // For erasing the book's area: opaque at the centre, clear 64 px out. Drawn in slices, so the fade is the
440	  // same width all round a rectangle of any size.
441	  const MASK = sprite(128, (g, size) => {
442	    const img = g.createImageData(size, size);
443	    for (let y = 0; y < size; y++) {
444	      for (let x = 0; x < size; x++) {
445	        const d = Math.min(1, Math.hypot(x + 0.5 - 64, y + 0.5 - 64) / 64);
446	        img.data[(y * size + x) * 4 + 3] = 255 * (1 - d * d * (3 - 2 * d));
447	      }
448	    }
449	    g.putImageData(img, 0, 0);
450	  });
451	
452	  function paint(t, dt) {
453	    if (inked) ctx.clearRect(0, 0, width, height);
454	    presence = ease(presence, 1, 0.8, dt);
455	    const lit = trackLamp(dt);
456	    let drew = drawHalo(t);
457	    drew = drawHaze(t) || drew;
458	    drew = drawPattern() || drew;
459	    for (const kind in KINDS) {
460	      if (!particles[kind].length) continue;
461	      for (const p of particles[kind]) KINDS[kind].draw(p, t, dt);
462	      drew = true;
463	    }
464	    if (lit) {
465	      drew = drawLens() || drew;
466	      drew = drawGlow() || drew;
467	    }
468	    ctx.globalAlpha = 1;
469	    if (drew) eraseBook();
470	    inked = drew;
471	  }
472	
473	  // The book ---------------------------------------------------------------------------------------------
474	
475	  // Sine waves whose periods never line up, so the movement doesn't visibly repeat. k is the strength.
476	  const IDLE = {
477	    float: (t, k) => `translate3d(${wave(t, 11) * 1.5 * k * unit}px, ${wave(t, 6.5) * 4 * k * unit}px, 0)`,
478	    breathe: (t, k) => `scale(${1 + (wave(t, 7) + 1) * 0.005 * k})`,
479	    drift: (t, k) =>
480	      `rotateX(${wave(t, 9) * 0.6 * k}deg) rotateY(${wave(t, 13, 1) * k}deg) translate3d(0, ${wave(t, 7) * 2 * k * unit}px, 0)`,
481	  };
482	
483	  function moveBook(t) {
484	    const k = (idle * settings.move) / 100;
485	    // A hair of rotation stops the browser snapping the book to whole pixels, which made Float and Breathe
486	    // move in visible steps.
487	    const hair = (0.1 + wave(t, 17, 2) * 0.06) * Math.min(k, 1);
488	    setBook(k > 0.01 ? `perspective(1600px) rotate(${hair}deg) ${IDLE[motion](t, k)}` : '');
489	  }
490	
491	  // With 'before', the book gets a layer of its own only while it moves. The fixes keep that layer whenever the book
492	  // may move, so the aayat are drawn once and moved whole, rather than possibly redrawn at each new size and tilt.
493	  function setBook(transform) {
494	    if (transform !== bookTransform) {
495	      bookTransform = transform;
496	      subject.style.transform = transform;
497	    }
498	    const mayMove = settings.text !== 'before' && settings.idle !== 'off' && settings.move > 0 && !reduceMotion.matches;
499	    const layer = Boolean(transform) || mayMove;
500	    if (layer !== bookLayer) {
501	      bookLayer = layer;
502	      subject.style.willChange = layer ? 'transform' : '';
503	    }
504	  }
505	
506	  // Loop ---------------------------------------------------------------------------------------------------
507	
508	  function resize() {
509	    width = canvas.clientWidth;
510	    height = canvas.clientHeight;
511	    unit = height / 900;
512	    dpr = Math.min(devicePixelRatio || 1, level === 'full' ? 1.5 : 1); // soft light doesn't need full retina sharpness
513	    canvas.width = Math.round(width * dpr);
514	    canvas.height = Math.round(height * dpr);
515	    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
516	    inked = false; // resizing clears the canvas
517	    buildPattern();
518	    for (const kind in KINDS) populate(kind);
519	    presence = 0;
520	  }
521	
522	  function running() {
523	    const air = settings.dust || settings.leaf || settings.glints || settings.haze || settings.halo || settings.pattern === 'faint';
524	    const book = settings.idle !== 'off' && settings.move > 0;
525	    const pointed = (settings.glow > 0 || settings.pattern === 'mouse') && mouse.matches;
526	    return visible && !reduceMotion.matches && level !== 'off' && Boolean(air || book || pointed);
527	  }
528	
529	  // Starts the loop if there is anything to animate; otherwise leaves the book still and the canvas clear.
530	  function refresh() {
531	    if (running()) return wake();
532	    idle = 0;
533	    setBook('');
534	    if (inked) ctx.clearRect(0, 0, width, height);
535	    inked = false;
536	  }
537	
538	  function wake() {
539	    if (raf) return;
540	    last = windowStart = frames = 0;
541	    raf = requestAnimationFrame(frame);
542	  }
543	
544	  function measure(now, dtMs) {
545	    if (gliding || now - lastMove < 1000 || now < WARMUP || document.hidden || dtMs > 250) {
546	      windowStart = 0; // not a fair moment to judge; a fresh window starts later
547	      return;
548	    }
549	    if (!windowStart) {
550	      windowStart = now;
551	      frames = 0;
552	      return;
553	    }
554	    frames++;
555	    if (now - windowStart < WINDOW) return;
556	    badWindows = (frames * 1000) / (now - windowStart) < MIN_FPS ? badWindows + 1 : 0;
557	    windowStart = 0;
558	    if (badWindows < BAD_WINDOWS) return;
559	    badWindows = 0;
560	    level = level === 'full' ? 'lite' : 'off';
561	    resize();
562	    refresh();
563	  }
564	
565	  // Uses elapsed time, so it moves at the same speed on 60 Hz and 144 Hz screens.
566	  function frame(now) {
567	    raf = 0;
568	    if (!running()) return refresh();
569	    const dtMs = last ? now - last : 1000 / 60;
570	    const dt = Math.min(dtMs, 50) / 1000;
571	    last = now;
572	    const t = now / 1000;
573	    const quiet = !gliding && now - lastMove > IDLE_DELAY;
574	    idle = ease(idle, quiet && settings.idle !== 'off' ? 1 : 0, quiet ? 1.2 : 0.12, dt);
575	    moveBook(t);
576	    paint(t, dt);
577	    measure(now, dtMs);
578	    if (!raf && running()) raf = requestAnimationFrame(frame);
579	  }
580	
581	  const moved = () => (lastMove = performance.now());
582	  addEventListener('scroll', moved, { passive: true });
583	  hero.addEventListener('bookmove', () => (gliding = true));
584	  hero.addEventListener('bookrest', () => {
585	    gliding = false;
586	    moved();
587	  });
588	  addEventListener(
589	    'pointermove',
590	    (e) => {
591	      if (e.pointerType !== 'mouse') return;
592	      pointer.x = e.clientX;
593	      pointer.y = e.clientY;
594	      pointer.inside = true;
595	    },
596	    { passive: true },
597	  );
598	  root.addEventListener('mouseleave', () => (pointer.inside = false));
599	  reduceMotion.addEventListener('change', refresh);
600	  new ResizeObserver(resize).observe(canvas);
601	  new IntersectionObserver(([entry]) => {
602	    visible = entry.isIntersecting;
603	    refresh();
604	  }).observe(hero);
605	
606	  // TRYOUT ------------------------------------------------------------------------------------------------
607	  // Phase 4 options, added to main.js's panel on this PC or a phone on the same wifi. Once the user picks: put
608	  // the picks in `settings`, delete what was switched off, then delete this block and the .readout CSS.
609	
610	  if (window.addOption) {
611	    const choose = (key, after) => (value) => {
612	      settings[key] = value;
613	      if (level !== 'full') {
614	        level = 'full';
615	        badWindows = 0;
616	        resize();
617	      }
618	      after?.(value);
619	      refresh();
620	    };
621	    const percent = (v) => (v ? `${v}%` : 'Off');
622	    for (const [kind, label] of [['dust', 'Gold dust'], ['leaf', 'Gold leaf'], ['glints', 'Glints']]) {
623	      addSlider(label, 0, 250, 5, settings[kind], percent, choose(kind, () => populate(kind, false)));
624	    }
625	    addSlider('Haze', 0, 100, 5, settings.haze, percent, choose('haze'));
626	    addSlider('Light behind book', 0, 100, 5, settings.halo, percent, choose('halo'));
627	    const patterns = mouse.matches ? { Off: 'off', Faint: 'faint', 'Under the mouse': 'mouse' } : { Off: 'off', Faint: 'faint' };
628	    addOption('Gold pattern', patterns, settings.pattern, choose('pattern'));
629	    if (mouse.matches) addSlider('Mouse glow', 0, 240, 5, settings.glow, (v) => (v ? `${v} px` : 'Off'), choose('glow'));
630	    addOption('Book when still', { Off: 'off', Float: 'float', Breathe: 'breathe', Drift: 'drift' }, settings.idle, choose('idle', (v) => v !== 'off' && (motion = v)));
631	    addSlider('Movement', 0, 300, 5, settings.move, (v) => `${v}%`, choose('move'));
632	    addOption('Aayat while moving', { 'As before': 'before', 'Fix A': 'steady', 'Fix B': 'flat' }, settings.text, choose('text', (v) => (root.dataset.ink = v === 'flat' ? 'flat' : '')));
633	
634	    // How smoothly this device runs: frames a second while scrolling and while still, counted separately.
635	    const readout = document.createElement('p');
636	    readout.className = 'readout';
637	    document.querySelector('.tryout').append(readout);
638	    const scrolling = { frames: 0, ms: 0, fps: null };
639	    const resting = { frames: 0, ms: 0, fps: null };
640	    let prev = 0;
641	    let since = 0;
642	    const meter = (now) => {
643	      const dt = prev ? now - prev : 0;
644	      prev = now;
645	      if (dt > 0 && dt < 250) {
646	        const bucket = gliding || now - lastMove < 300 ? scrolling : resting;
647	        bucket.frames++;
648	        bucket.ms += dt;
649	      }
650	      if (now - since > 1000) {
651	        since = now;
652	        for (const b of [scrolling, resting]) {
653	          if (b.ms > 300) b.fps = Math.round((b.frames * 1000) / b.ms);
654	          b.frames = b.ms = 0;
655	        }
656	        const show = (b) => b.fps ?? '–';
657	        const note = {
658	          full: '',
659	          lite: ' Effects were lightened because this device was slow while the book was still.',
660	          off: ' Effects were switched off because this device was slow while the book was still. Choose any effect option to turn them back on.',
661	        }[level];
662	        readout.textContent = `Smoothness on this device (60 is smooth): scrolling ${show(scrolling)}, still ${show(resting)} frames a second.${note}`;
663	      }
664	      requestAnimationFrame(meter);
665	    };
666	    requestAnimationFrame(meter);
667	  }
668	})();
