if (!reduceMotion.matches) {
  close.classList.add('pending');
  const reveal = new IntersectionObserver(
    ([entry]) => {
      if (!entry.isIntersecting) return;
      close.classList.remove('pending');
      reveal.disconnect();
    },
    { rootMargin: '0px 0px -15% 0px' },
  );
