/* Phase 5: the ending, one line and two ways in, on the screen after the book. The gold dust carries on behind it
   on a second canvas (atmosphere.js). The spacing, 4px corners, no shadow and gentle rise follow
   taste-skill:minimalist-skill; one gold button leads and the other stays quieter (ui-ux-pro-max: primary-action). */
.close {
  position: relative;
  isolation: isolate; /* keeps .inner over the dust without lifting it over the options panels */
  display: grid;
  place-items: center;
  min-height: 100vh;
  min-height: 100svh;
  padding: 6rem 1.5rem;
}

.close .inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2.25rem;
  width: 100%;
  max-width: 40rem;
  text-align: center;
  transition:
    opacity 600ms cubic-bezier(0.16, 1, 0.3, 1),
    transform 600ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* Set by main.js until the ending first scrolls into view. */
.close.pending .inner {
  opacity: 0;
  transform: translateY(12px);
}

.close h2 {
  margin: 0;
  max-width: 30ch;
  font-size: clamp(1.375rem, 1.1rem + 1.1vw, 2rem);
  font-weight: 300;
  line-height: 1.35;
  letter-spacing: 0.01em;
  text-wrap: balance;
}

