1	/* Phase 1: hero scroll animation. Phase 2: theme tokens, fonts and the headline. Phase 3: aayat on the pages.
2	   Phase 5: the ending. */
3	
4	*,
5	*::before,
6	*::after {
7	  box-sizing: border-box;
8	}
9	
10	/* Dark theme, from design-system/quran-landing/MASTER.md. The background is the footage's own #1F1A18
11	   rather than MASTER's #1C1917 (three shades apart), so the frame's edges disappear without a blend.
12	   Cinzel for the headline and the bright gold were chosen by the user from on-page options. */
13	:root {
14	  --color-background: #1F1A18;
15	  --color-foreground: #FAFAF9;
16	  --color-muted-foreground: #A8A29E;
17	  --color-accent: #D4AF37;
18	  --font-display: Cinzel, 'Trajan Pro', Georgia, serif;
19	  --font-body: Jost, system-ui, sans-serif;
20	  --font-arabic: 'Amiri Quran', 'Scheherazade New', serif;
21	  color-scheme: dark;
22	}
23	
24	html,
25	body {
26	  margin: 0;
27	  background: var(--color-background);
28	  color: var(--color-foreground);
29	  font-family: var(--font-body);
30	}
31	
32	/* No scroll bar: it broke the dark scene. Scrolling works the same without it. */
33	html {
34	  scrollbar-width: none;
35	}
36	
37	html::-webkit-scrollbar {
38	  display: none;
39	}
40	
41	/* A tall section; the stage inside it stays pinned while it scrolls past. Its height is one screen
42	   plus the timeline in main.js (4.1 screens): the rest, the opening, then one group of aayat, before
43	   the page moves on to the ending. Phones scroll two thirds as far, because a finger moves further per
44	   swipe than a mouse wheel per click. */
45	.hero {
46	  position: relative;
47	  height: 510vh;
48	}
49	
50	.stage {
51	  position: sticky;
52	  top: 0;
53	  height: 100vh;
54	  height: 100svh; /* the book stays whole behind mobile browser bars */
55	  overflow: hidden;
56	}
57	
58	/* The book and its aayat sit together in .subject, which atmosphere.js moves slightly while nobody is
59	   scrolling, inside .book, which makes room for the ending in the "Under the book" option. The light in the
60	   air is a canvas over them (and a second one behind the ending), and never catches clicks. */
61	.book,
62	.subject,
63	.air {
64	  position: absolute;
65	  inset: 0;
66	}
67	
68	.subject canvas,
69	.air {
70	  display: block;
71	  width: 100%;
72	  height: 100%;
73	}
74	
75	.air {
76	  pointer-events: none;
77	}
78	
79	/* The headline, centred in the space under the closed book. --book-h is the book's height on screen,
80	   set by main.js, which also fades it out as the cover starts to open. */
81	.wordmark {
82	  position: absolute;
83	  z-index: 1; /* over .subject: the frame's feathered bottom edge reaches the headline on some screens */
84	  left: 0;
85	  right: 0;
86	  bottom: calc((50% - var(--book-h, 60svh) / 2) / 2);
87	  transform: translateY(50%);
88	  padding: 0 1.5rem;
89	  text-align: center;
90	}
91	
92	.wordmark h1 {
93	  margin: 0;
94	  padding-left: 0.2em; /* balances the letter-spacing after the last letter, so the text sits truly centred */
95	  font-family: var(--font-display);
96	  font-size: clamp(1.125rem, 0.9rem + 1vw, 1.625rem);
97	  font-weight: 500;
98	  line-height: 1.2;
99	  letter-spacing: 0.2em;
100	  text-transform: uppercase;
101	  color: var(--color-accent);
102	}
103	
104	.wordmark p {
105	  margin: 0.7em 0 0;
106	  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
107	  font-weight: 300;
108	  letter-spacing: 0.06em;
109	  color: var(--color-muted-foreground);
110	}
111	
112	/* Aayat, laid over the open book's pages. The numbers are page positions in the 1280x720 footage:
113	   left page x 262-636, right page x 645-1020, both y 80-640. main.js sets --s (the book's scale) and
114	   --x0/--y0 (where the footage's corner sits once the book is open), and each group's opacity. */
115	.aayat {
116	  position: absolute;
117	  inset: 0;
118	  pointer-events: none;
119	}
120	
121	.group {
122	  position: absolute;
123	  inset: 0;
124	  opacity: 0;
125	  transition: opacity 600ms cubic-bezier(0.32, 0.72, 0, 1); /* main.js only switches opacity between 0 and 1 */
126	  mix-blend-mode: multiply; /* the ink sits in the paper, so the paper's shading shows through it */
127	}
128	
129	.page {
130	  position: absolute;
131	  top: calc(var(--y0, 0px) + 80px * var(--s, 1));
132	  width: calc(375px * var(--s, 1));
133	  height: calc(560px * var(--s, 1));
134	  padding: calc(56px * var(--s, 1)) calc(40px * var(--s, 1));
135	  display: flex;
136	  flex-direction: column;
137	  justify-content: safe center;
138	  gap: 1.25em;
139	  overflow: hidden;
140	  text-align: center;
141	  color: #2B211B; /* dark ink, 14:1 on the cream page */
142	}
143	
144	.page p {
145	  margin: 0;
146	}
147	
148	.page.right {
149	  left: calc(var(--x0, 0px) + 645px * var(--s, 1));
150	  font-size: calc(30px * var(--s, 1));
151	}
152	
153	.page.left {
154	  left: calc(var(--x0, 0px) + 262px * var(--s, 1));
155	  font-size: calc(16px * var(--s, 1));
156	}
157	
158	.arabic {
159	  font-family: var(--font-arabic);
160	  line-height: 2.2; /* room for the marks above and below the letters */
161	}
162	
163	.marker {
164	  color: #A16207; /* gold only for the small accents */
165	}
166	
167	.surah {
168	  padding-left: 0.15em;
169	  font-family: var(--font-display);
170	  font-size: 1.2em;
171	  letter-spacing: 0.15em;
172	  text-transform: uppercase;
173	  color: #8A6A1F;
174	}
175	
176	.meaning {
177	  display: none;
178	  font-weight: 400;
179	  line-height: 1.6;
180	  color: #3A302A;
181	}
182	
183	.ref {
184	  font-size: 0.85em;
185	  letter-spacing: 0.08em;
186	  color: #6B5E55;
187	}
188	
189	/* Phase 5: the ending, one line and two ways in, on the screen after the book. The gold dust carries on behind it
190	   on a second canvas (atmosphere.js). The spacing, 4px corners, no shadow and gentle rise follow
191	   taste-skill:minimalist-skill; one gold button leads and the other stays quieter (ui-ux-pro-max: primary-action). */
192	.close {
193	  position: relative;
194	  isolation: isolate; /* keeps .inner over the dust without lifting it over the options panels */
195	  display: grid;
196	  place-items: center;
197	  min-height: 100vh;
198	  min-height: 100svh;
199	  padding: 6rem 1.5rem;
200	}
201	
202	.close .inner {
203	  position: relative;
204	  z-index: 1;
205	  display: flex;
206	  flex-direction: column;
207	  align-items: center;
208	  gap: 2.25rem;
209	  width: 100%;
210	  max-width: 40rem;
211	  text-align: center;
212	  transition:
213	    opacity 600ms cubic-bezier(0.16, 1, 0.3, 1),
214	    transform 600ms cubic-bezier(0.16, 1, 0.3, 1);
215	}
216	
217	/* Set by main.js until the ending first scrolls into view. */
218	.close.pending .inner {
219	  opacity: 0;
220	  transform: translateY(12px);
221	}
222	
223	.close h2 {
224	  margin: 0;
225	  max-width: 30ch;
226	  font-size: clamp(1.375rem, 1.1rem + 1.1vw, 2rem);
227	  font-weight: 300;
228	  line-height: 1.35;
229	  letter-spacing: 0.01em;
230	  text-wrap: balance;
231	}
232	
233	.entry {
234	  display: flex;
235	  flex-wrap: wrap;
236	  justify-content: center;
237	  gap: 0.75rem 1rem;
238	}
239	
240	.button {
241	  display: inline-flex;
242	  align-items: center;
243	  justify-content: center;
244	  min-height: 48px;
245	  padding: 0 1.75rem;
246	  border: 1px solid var(--color-accent);
247	  border-radius: 4px;
248	  font-size: 0.9375rem;
249	  letter-spacing: 0.06em;
250	  color: var(--color-accent); /* 8:1 on the background */
251	  text-decoration: none;
252	  cursor: pointer;
253	  transition:
254	    background-color 200ms ease,
255	    border-color 200ms ease,
256	    color 200ms ease,
257	    transform 200ms ease;
258	}
259	
260	.button.primary {
261	  background: var(--color-accent);
262	  color: var(--color-background); /* 8:1 on the gold */
263	}
264	
265	.button:hover {
266	  background: rgba(212, 175, 55, 0.1);
267	}
268	
269	.button.primary:hover {
270	  border-color: #E2C35C;
271	  background: #E2C35C;
272	}
273	
274	.button:active {
275	  transform: scale(0.98);
276	}
277	
278	.button:focus-visible {
279	  outline: 2px solid var(--color-accent);
280	  outline-offset: 4px;
281	}
282	
283	@media (max-width: 767px) {
284	  .close {
285	    padding: 4rem 1.5rem;
286	  }
287	
288	  .entry {
289	    flex-direction: column;
290	    width: 100%;
291	    max-width: 20rem;
292	  }
293	}
294	
295	@media (max-width: 767px) {
296	  .hero {
297	    height: 373vh; /* one screen plus two thirds of 4.1 */
298	  }
299	
300	  /* The pages are too small for a second block of text, so the left page's text sits under the book. */
301	  .group {
302	    mix-blend-mode: normal;
303	  }
304	
305	  .page.left {
306	    left: 1.5rem;
307	    right: 1.5rem;
308	    width: auto;
309	    top: calc(var(--y0, 0px) + 650px * var(--s, 1) + 1rem);
310	    height: calc(var(--y0, 0px) + 70px * var(--s, 1) - 2rem);
311	    padding: 0;
312	    font-size: 0.875rem;
313	    color: var(--color-muted-foreground);
314	  }
315	
316	  .page.left .surah {
317	    color: var(--color-accent);
318	  }
319	
320	  .page.left .meaning,
321	  .page.left .ref {
322	    color: var(--color-muted-foreground);
323	  }
324	}
325	
326	/* Reduced motion: no scrubbing, just the open book with a random group of aayat. */
327	.still .hero {
328	  height: auto;
329	}
330	
331	.still .group {
332	  transition: none;
333	}
334	
335	.still .close.pending .inner {
336	  opacity: 1;
337	  transform: none;
338	}
339	
340	/* TRYOUT: phase 3 options, set on <html> by main.js. Once the user picks, move the picks above and
341	   delete everything below. */
342	[data-arabic='scheherazade'] {
343	  --font-arabic: 'Scheherazade New', 'Amiri Quran', serif;
344	}
345	
346	[data-left='meaning'] .meaning {
347	  display: block;
348	}
349	
350	/* Phase 4, "Aayat while moving: Fix B" (set by atmosphere.js): plain ink, as on phones. */
351	[data-ink='flat'] .group {
352	  mix-blend-mode: normal;
353	}
354	
355	.tryout input[type='range'] {
356	  width: 10em;
357	  accent-color: #d4af37;
358	}
359	
360	.tryout output {
361	  min-width: 7em;
362	  font-variant-numeric: tabular-nums;
363	}
364	
365	.tryout {
366	  position: fixed;
367	  right: 12px; /* bottom-right, clear of the headline picker (wordmark-options.js) in the bottom-left */
368	  bottom: 12px;
369	  max-width: calc(100vw - 24px);
370	  max-height: calc(100svh - 24px); /* scrolls inside itself on a phone */
371	  overflow-y: auto;
372	  padding: 10px 12px;
373	  border: 1px solid #3F3A37;
374	  border-radius: 12px;
375	  background: rgba(0, 0, 0, 0.7);
376	  font: 13px/1 system-ui, sans-serif;
377	  color: #e7e0d8;
378	}
379	
380	.tryout .readout {
381	  max-width: 34em;
382	  margin: 10px 0 2px;
383	  line-height: 1.4;
384	  color: #A8A29E;
385	  font-variant-numeric: tabular-nums;
386	}
387	
388	.tryout summary {
389	  padding: 4px 0;
390	  cursor: pointer;
391	}
392	
393	/* Groups of options inside the panel, from tryoutGroup in main.js. */
394	.tryout details {
395	  margin-top: 10px;
396	  padding-top: 4px;
397	  border-top: 1px solid #3F3A37;
398	}
399	
400	.tryout div {
401	  display: flex;
402	  flex-wrap: wrap;
403	  align-items: center;
404	  gap: 6px;
405	  margin-top: 8px;
406	}
407	
408	.tryout span {
409	  min-width: 10em;
410	  color: #A8A29E;
411	}
412	
413	.tryout button {
414	  padding: 10px 14px;
415	  border: 1px solid #5c5048;
416	  border-radius: 999px;
417	  background: transparent;
418	  color: #e7e0d8;
