1	// Phase 1: the hero scroll animation. Phase 2: the headline with the closed book. Phase 3: aayat on the open pages.
2	// Phase 5: the ending after the book, with its options.
3	// Retouched video frames of the Qur'an opening, drawn to a canvas by scroll position.
4	// Spec: WEBSITE-BUILD.md sections 2 to 4; the settings the user chose are under section 7.
5	
6	(() => {
7	  const clamp = (v) => Math.min(1, Math.max(0, v));
8	  const smoothstep = (t) => t * t * (3 - 2 * t);
9	
10	  // Frames --------------------------------------------------------------------
11	
12	  const SKIP = [39, 40]; // identical to f038, a hold in the source video
13	  const urls = [];
14	  for (let i = 0; i <= 88; i++) {
15	    if (!SKIP.includes(i)) urls.push(`assets/hero/frames/f${String(i).padStart(3, '0')}.png`);
16	  }
17	  const LAST = urls.length - 1; // 87 frames, indices 0..86
18	
19	  // Geometry, in pixels of the 1280x720 frames ----------------------------------
20	
21	  const SRC_W = 1280;
22	  const SRC_H = 720;
23	  const BOOK_LEFT = 255;   // left edge of the book; it never moves in the footage
24	  const BOOK_H = 580;      // y 70-650, centred on the frame's middle
25	  const SPINE = 640;       // right edge until the cover passes upright
26	  const OPEN_RIGHT = 1037; // right edge fully open
27	  const FEATHER_X = 180;   // how far the frame's rectangle fades into the stage
28	  const FEATHER_Y = 40;
29	
30	  // Timeline, in screen heights of scrolling on a computer -----------------------
31	  // Phones scroll two thirds as far for everything (the hero is shorter there, in styles.css).
32	
33	  const REST = 0.45;  // closed book with the headline
34	  const OPEN = 2.25;  // the cover opens (the same scrolling as when the user signed off phase 1)
35	  const SETTLE = 0.4; // open pages
36	  const AYAH = 1;     // time to read the aayat before the page moves on
37	  const TOTAL = REST + OPEN + SETTLE + AYAH; // 4.1; .hero in styles.css is one screen taller than this
38	  const NAME_GONE = 8; // the headline has faded out by this frame, early in the opening
39	
40	  // Smoothing ---------------------------------------------------------------------
41	
42	  // A mouse wheel scrolls in steps, so everything glides toward the scroll position instead of
43	  // jumping to it, and the book cross-fades between frames. The user chose this "slow glide" by eye.
44	  let glide = 0.28; // roughly the seconds it takes to close two thirds of the gap; 0 jumps straight there
45	  let blend = true; // cross-fade neighbouring frames, rather than showing whole frames only
46	  // Stopped between two frames, the cross-fade settles onto the nearer frame over this many seconds: held still, it looks blurred.
47	  const SHARPEN = 0.25;
48	  // Once scrolling reaches this, the aayat fade in by themselves (the transition on .group), not with the scroll.
49	  const APPEAR = REST + OPEN * 0.9;
50	
51	  // A book left half open opens or closes by itself once scrolling stops: toward the nearer end, or the way the
52	  // visitor was scrolling. 'off' leaves it where it stopped.
53	  let finish = 'direction';
54	  let finishSpeed = 1;     // screens of scrolling a second; a half-open book is about one screen from either end
55	  const FINISH_WAIT = 180; // ms without scrolling before it finishes
56	
57	  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
58	  const hero = document.querySelector('.hero');
59	  const stage = hero.querySelector('.stage');
60	  const subject = stage.querySelector('.subject'); // the book and its aayat, moved together by atmosphere.js
61	  const canvas = subject.querySelector('canvas');
62	  const wordmark = stage.querySelector('.wordmark');
63	  const ctx = canvas.getContext('2d');
64	  const close = document.querySelector('.close'); // the ending, after the book
65	  const closeInner = close.querySelector('.inner');
66	
67	  const frames = []; // decoded images by index, filled in as they arrive
68	  const rights = []; // measured right edge of the book in each frame
69	  const started = new Set();
70	  const groups = []; // one element per group of aayat, filled in when aayat.json arrives
71	
72	  let scale = 1;      // footage pixels to CSS pixels, set on resize
73	  let pos = null;     // scroll position shown, in screens; lags the real one while gliding
74	  let painted = null; // position last shown
75	  let drawn = null;   // frame last drawn; fractional between frames
76	  let last = 0;       // time of the previous glide step, 0 when at rest
77	  let dirty = true;
78	  let queued = false;
79	  let visible = true;
80	  let showing = false; // whether the pages show aayat
81	  let current = -1;   // the group of aayat last picked
82	  let previous = -1;  // the last group shown, so the next pass shows a different one
83	  let moving = false; // still gliding toward the scroll position; atmosphere.js keeps the book still meanwhile
84	  let sharpen = 1;    // 0 while moving, 1 once settled onto a whole frame
85	  let direction = 0;  // 1 when the visitor last scrolled down, -1 up
86	  let lastY = scrollY;
87	  let touching = false;
88	  let finishTimer = 0;
89	  let autoScroll = 0; // the animation frame of a scroll the page started itself, 0 when none
90	  let ended = false;  // scrolling has reached the end of the book's screens
91	
92	  // Loading -----------------------------------------------------------------------
93	
94	  function load(i) {
95	    if (started.has(i)) return;
96	    started.add(i);
97	    const img = new Image();
98	    img.src = urls[i];
99	    img.decode().then(
100	      () => {
101	        frames[i] = img;
102	        rights[i] = measureRight(img);
103	        if (i >= LAST - 3) place(); // the open book's measured edge sets where the pages are
104	        dirty = true;
105	        schedule();
106	      },
107	      () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
108	    );
109	  }
110	
111	  // First and last frames, then coarse to fine, so scrubbing works before everything arrives.
112	  function loadAll() {
113	    load(0);
114	    load(LAST);
115	    for (const step of [8, 4, 2, 1]) {
116	      for (let i = 0; i <= LAST; i += step) load(i);
117	    }
118	  }
119	
120	  // Once the cover passes upright its cream lining faces the camera, so the book's right
121	  // edge is the rightmost bright pixel along the middle row, and never less than the spine.
122	  const probe = document.createElement('canvas');
123	  probe.width = SRC_W;
124	  probe.height = 1;
125	  const probeCtx = probe.getContext('2d', { willReadFrequently: true });
126	
127	  function measureRight(img) {
128	    try {
129	      probeCtx.drawImage(img, 0, SRC_H / 2, SRC_W, 1, 0, 0, SRC_W, 1);
130	      const px = probeCtx.getImageData(0, 0, SRC_W, 1).data;
131	      for (let x = SRC_W - 1; x > SPINE; x--) {
132	        if (px[x * 4] + px[x * 4 + 1] + px[x * 4 + 2] > 300) return x + 1;
133	      }
134	      return SPINE;
135	    } catch {
136	      return null; // pixels unreadable, e.g. opened as a file rather than through serve.js
137	    }
138	  }
139	
140	  // Averaged over nearby frames so the centring glides instead of stepping.
141	  function rightEdge(i) {
142	    let sum = 0;
143	    let n = 0;
144	    for (let j = Math.max(0, i - 3); j <= Math.min(LAST, i + 3); j++) {
145	      if (rights[j] != null) {
146	        sum += rights[j];
147	        n++;
148	      }
149	    }
150	    return n ? sum / n : SPINE + ((OPEN_RIGHT - SPINE) * i) / LAST;
151	  }
