153	  // Aayat -------------------------------------------------------------------------
154	  // The exact text comes from aayat.json, written by fetch-aayat.js from Quran.com. Never typed by hand.
155	
156	  const aayat = document.createElement('div');
157	  aayat.className = 'aayat';
158	  subject.append(aayat);
159	
160	  function el(tag, className, text) {
161	    const node = document.createElement(tag);
162	    node.className = className;
163	    if (text) node.textContent = text;
164	    return node;
165	  }
