167	  // Arabic on the right page, the first page in a mushaf, each ayah closed by its numbered marker.
168	  // The left page carries the surah name, reference and English meaning.
169	  function renderGroup({ ref, surah, aayat: verses }) {
170	    const group = el('section', 'group');
171	    const right = el('div', 'page right');
172	    const arabic = el('p', 'arabic');
173	    arabic.lang = 'ar';
174	    arabic.dir = 'rtl';
175	    for (const { key, text } of verses) {
176	      const marker = el('span', 'marker', `۝${Number(key.split(':')[1]).toLocaleString('ar-u-nu-arab')}`);
177	      marker.setAttribute('aria-hidden', 'true');
178	      arabic.append(`${text} `, marker, ' ');
179	    }
180	    right.append(arabic);
181	    const left = el('div', 'page left');
182	    left.append(
183	      el('p', 'surah', surah),
184	      el('p', 'meaning', verses.map((v) => v.translation).join(' ')),
185	      el('p', 'ref', ref.replace('-', '–')),
186	    );
187	    group.append(right, left);
188	    return group;
189	  }
190	
191	  fetch('aayat.json')
192	    .then((res) => res.json())
193	    .then((data) => {
194	      for (const g of data.groups) groups.push(aayat.appendChild(renderGroup(g)));
195	      fit();
196	      dirty = true;
197	      schedule();
198	    })
199	    .catch(() => console.warn('No aayat yet: run fetch-aayat.js'));
