201	  // Where the open book's pages are: CSS lays the text over them from these.
202	  function place() {
203	    const open = (BOOK_LEFT + rightEdge(LAST)) / 2;
204	    stage.style.setProperty('--s', scale);
205	    stage.style.setProperty('--x0', `${canvas.clientWidth / 2 - open * scale}px`);
206	    stage.style.setProperty('--y0', `${(canvas.clientHeight - SRC_H * scale) / 2}px`);
207	    stage.style.setProperty('--book-h', `${BOOK_H * scale}px`);
208	    placeEnding();
209	  }
210	
211	  // Shrinks a page's text until it fits, for aayat longer than the page holds at its normal size.
212	  function fit() {
213	    for (const page of aayat.querySelectorAll('.page')) {
214	      page.style.fontSize = '';
215	      let size = parseFloat(getComputedStyle(page).fontSize);
216	      while (page.scrollHeight > page.clientHeight && size > 10) {
217	        size *= 0.94;
218	        page.style.fontSize = `${size}px`;
219	      }
220	    }
221	  }
222	
223	  // One group at a time, picked at random each time the pages come into view. It fades in by itself once
224	  // the book is open and stays; scrolling back before that fades it out, so the next pass picks again.
225	  // Under reduced motion a random group is simply shown.
226	  function showAayat(s, still) {
227	    const show = still || s >= APPEAR;
228	    if (show === showing || !groups.length) return;
229	    showing = show;
230	    if (show) current = pick();
231	    groups.forEach((group, k) => {
232	      group.style.opacity = show && k === current ? 1 : 0;
233	    });
234	  }
235	
236	  // A random group, never the one shown last time.
237	  function pick() {
238	    let k;
239	    do k = Math.floor(Math.random() * groups.length);
240	    while (groups.length > 1 && k === previous);
241	    return (previous = k);
242	  }
243	
244	  // The ending ----------------------------------------------------------------------
245	  // One line and two ways in, on the screen after the book. It rises gently into view the first time it scrolls in
246	  // (styles.css), except under reduced motion.
247	
248	  if (!reduceMotion.matches) {
249	    close.classList.add('pending');
250	    const reveal = new IntersectionObserver(
251	      ([entry]) => {
252	        if (!entry.isIntersecting) return;
253	        close.classList.remove('pending');
254	        reveal.disconnect();
255	      },
256	      { rootMargin: '0px 0px -15% 0px' },
257	    );
258	    reveal.observe(closeInner);
259	  }
260	
261	  // TRYOUT "Under the book": when scrolling reaches the end, the open book rises and shrinks so the ending fits
262	  // under it (styles.css). Scrolling back a little undoes it; the gap between the two points stops it flickering.
263	  function endAt(s) {
264	    const end = s >= TOTAL - 0.1 || (ended && s > TOTAL - 0.4);
265	    if (end !== ended) hero.classList.toggle('ended', (ended = end));
266	  }
267	
268	  // How far the book rises and shrinks for "Under the book", and where the ending goes: the book stays full size if
269	  // both fit, and the two sit centred on the screen together. In footage pixels the open book, with the page edges
270	  // that reach past it, runs from 10 above its top to 44 below its bottom.
271	  function placeEnding() {
272	    const h = canvas.clientHeight;
273	    const tall = (BOOK_H + 54) * scale;
274	    const above = (BOOK_H / 2 + 10) * scale; // from the middle of the screen to the top of the book
275	    const gap = Math.max(24, h * 0.05);
276	    const text = closeInner.offsetHeight;
277	    const k = Math.min(1, Math.max(0.55, (h - 3 * gap - text) / tall));
278	    const top = Math.max(gap, (h - tall * k - gap - text) / 2);
279	    const vars = document.documentElement.style;
280	    vars.setProperty('--end-scale', k);
281	    vars.setProperty('--end-y', `${top - h / 2 + above * k}px`);
282	    vars.setProperty('--end-top', `${top + tall * k + gap}px`);
283	  }
