285	  // Drawing -----------------------------------------------------------------------
286	
287	  // Cross-fades the two frames either side of a position, or while they are still loading, draws
288	  // the nearest frame that has arrived. Returns false while no frame has loaded yet.
289	  function draw(at) {
290	    const a = Math.floor(at);
291	    const b = Math.min(a + 1, LAST);
292	    const f = at - a;
293	    const fade = f > 0 && !!frames[a] && !!frames[b];
294	    const base = fade ? a : nearestLoaded(Math.round(at));
295	    if (base < 0) return false;
296	
297	    const width = canvas.clientWidth;
298	    const height = canvas.clientHeight;
299	    // The book is centred by choosing which part of the frame is drawn, never by moving the canvas.
300	    const right = rightEdge(a) + (rightEdge(b) - rightEdge(a)) * f;
301	    const centre = (BOOK_LEFT + right) / 2;
302	    const w = SRC_W * scale;
303	    const h = SRC_H * scale;
304	    const x = width / 2 - centre * scale;
305	    const y = (height - h) / 2;
306	
307	    ctx.globalCompositeOperation = 'source-over';
308	    ctx.clearRect(0, 0, width, height);
309	    ctx.drawImage(frames[base], x, y, w, h);
310	    if (fade) {
311	      ctx.globalAlpha = f;
312	      ctx.drawImage(frames[b], x, y, w, h);
313	      ctx.globalAlpha = 1;
314	    }
315	    featherEdges(x, y, w, h);
316	
317	    // Where the book is on screen, so atmosphere.js keeps its dust and light off it.
318	    const top = y + ((SRC_H - BOOK_H) / 2) * scale;
319	    hero.book = { left: x + BOOK_LEFT * scale, right: x + right * scale, top, bottom: top + BOOK_H * scale, scale };
320	    return true;
321	  }
322	
323	  // Fades a drawn rectangle out at its edges so it never shows against the stage.
324	  function featherEdges(x, y, w, h) {
325	    ctx.globalCompositeOperation = 'destination-in';
326	    ctx.fillStyle = feather(ctx.createLinearGradient(x, 0, x + w, 0), FEATHER_X / SRC_W);
327	    ctx.fillRect(x, y, w, h);
328	    ctx.fillStyle = feather(ctx.createLinearGradient(0, y, 0, y + h), FEATHER_Y / SRC_H);
329	    ctx.fillRect(x, y, w, h);
330	    ctx.globalCompositeOperation = 'source-over';
331	  }
332	
333	  function feather(gradient, edge) {
334	    gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
335	    gradient.addColorStop(edge, '#000');
336	    gradient.addColorStop(1 - edge, '#000');
337	    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
338	    return gradient;
339	  }
340	
341	  // How far the hero has been scrolled, in computer screen heights (0 to TOTAL).
342	  function targetScroll() {
343	    const range = hero.offsetHeight - stage.offsetHeight;
344	    return range > 0 ? clamp(-hero.getBoundingClientRect().top / range) * TOTAL : 0;
345	  }
346	
347	  // The book's frame at a scroll position; smoothstep eases into and out of the opening.
348	  function frameAt(s) {
349	    return smoothstep(clamp((s - REST) / OPEN)) * LAST;
350	  }
351	
352	  function nearestLoaded(i) {
353	    for (let d = 0; d <= LAST; d++) {
354	      if (frames[i - d]) return i - d;
355	      if (frames[i + d]) return i + d;
356	    }
357	    return -1;
358	  }
359	
360	  function schedule() {
361	    if (queued) return;
362	    queued = true;
363	    requestAnimationFrame(step);
364	  }
365	
366	  // Each animation frame, moves part of the way toward the scroll position and keeps going until it arrives,
367	  // then settles onto a whole frame. Uses elapsed time, so it feels the same on 60 Hz and 144 Hz screens.
368	  function step(now) {
369	    queued = false;
370	    if (!visible) {
371	      last = 0;
372	      return;
373	    }
374	    const target = targetScroll();
375	    const dt = last ? Math.min(now - last, 50) / 1000 : 1 / 60;
376	    if (pos === null || reduceMotion.matches || !glide) {
377	      pos = target;
378	    } else {
379	      pos += (target - pos) * (1 - Math.exp(-dt / glide));
380	      if (Math.abs(target - pos) < 0.0005) pos = target;
381	    }
382	    sharpen = pos === target ? Math.min(1, sharpen + dt / SHARPEN) : Math.max(0, sharpen - (3 * dt) / SHARPEN);
383	    last = pos === target && sharpen === 1 ? 0 : now;
384	    paint();
385	    if (moving !== (pos !== target)) {
386	      moving = pos !== target;
387	      hero.dispatchEvent(new Event(moving ? 'bookmove' : 'bookrest'));
388	    }
389	    if (last) schedule();
390	  }
391	
392	  // Updates the headline and aayat, and redraws the book only when its frame, the size or the loaded
393	  // frames have changed. Under reduced motion the book is shown open and the headline stays.
394	  function paint() {
395	    if (pos === null) return;
396	    const still = reduceMotion.matches;
397	    const exact = frameAt(pos);
398	    const whole = Math.round(exact);
399	    const frame = still ? LAST : blend ? exact + (whole - exact) * smoothstep(sharpen) : whole;
400	    if (pos !== painted || dirty) {
401	      wordmark.style.opacity = still ? 1 : 1 - clamp(frame / NAME_GONE);
402	      showAayat(pos, still);
403	      endAt(pos);
404	      painted = pos;
405	    }
406	    if (frame !== drawn || dirty) {
407	      if (draw(frame)) {
408	        drawn = frame;
409	        dirty = false;
410	      }
411	    }
412	  }
413	
414	  function resize() {
415	    const width = canvas.clientWidth;
416	    const height = canvas.clientHeight;
417	    const dpr = Math.min(devicePixelRatio || 1, 2);
418	    canvas.width = Math.round(width * dpr);
419	    canvas.height = Math.round(height * dpr);
420	    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
421	    ctx.imageSmoothingQuality = 'high';
422	    // One size for the whole opening: the open book always fits, and the 720p footage is
423	    // never stretched past its own size.
424	    scale = Math.min((height * 0.8) / BOOK_H, (width * 0.88) / (OPEN_RIGHT - BOOK_LEFT), 1);
425	    place();
426	    fit();
427	    dirty = true;
428	    paint(); // draw now: resizing the canvas has just cleared it
429	    schedule(); // the hero's height follows the window, so the scroll position may now mean a different frame
430	  }
431	
432	  // Reduced motion: no scrubbing, just the open book, and only its frame is loaded.
433	  function applyMotion() {
434	    document.documentElement.classList.toggle('still', reduceMotion.matches);
435	    if (reduceMotion.matches) load(LAST);
436	    else loadAll();
437	    dirty = true;
438	    schedule();
439	  }
