441	  // TRYOUT --------------------------------------------------------------------------
442	  // Options shown only on this PC or a phone on the same wifi. Once the user picks: put the picks in the
443	  // settings above and in styles.css, then delete this block, the TRYOUT part of styles.css and the
444	  // unused Arabic font in index.html.
445	
446	  if (/^(localhost|[\d.]+)$/.test(location.hostname)) {
447	    const narrow = matchMedia('(max-width: 767px)').matches;
448	    const panel = document.createElement('details');
