478	          pick(value);
479	        });
480	        row.append(b);
481	      }
482	      group.append(row);
483	    };
484	
485	    // A slider with its value shown beside it, in the words `format` gives.
486	    window.addSlider = (label, min, max, step, initial, format, pick) => {
487	      const row = document.createElement('div');
488	      const range = el('input', '');
489	      Object.assign(range, { type: 'range', min, max, step, value: initial });
