501	    const redraw = () => {
502	      dirty = true;
503	      schedule();
504	    };
505	    const retime = (set) => (value) => {
506	      set(value);
507	      redraw();
508	    };
509	    const setData = (key) => (value) => {
510	      document.documentElement.dataset[key] = value;
511	      fit();
512	    };
513	    tryoutGroup('Opening and aayat');
514	    const glideText = (v) => (v ? `${v.toFixed(2)} s${v === 0.28 ? ' (your pick)' : ''}` : 'Off');
515	    addSlider('Opening glide', 0, 0.5, 0.01, glide, glideText, retime((v) => (glide = v)));
516	    addOption('Blend frames', { Off: false, On: true }, blend, retime((v) => (blend = v)));
517	    addOption('Half-open book', { Stays: 'off', 'Nearer end': 'nearest', 'Way you scrolled': 'direction' }, finish, (v) => (finish = v));
518	    addSlider('Auto open/close speed', 25, 300, 5, finishSpeed * 100, (v) => `${v}%`, (v) => (finishSpeed = v / 100));
519	    addOption('Arabic lettering', { 'Amiri Quran': 'amiri', Scheherazade: 'scheherazade' }, 'amiri', setData('arabic'));
520	    addOption('Left page', { 'Surah name': 'name', 'English meaning': 'meaning' }, 'name', setData('left'));
521	    if (narrow) {
522	      const phoneScroll = setData('phoneScroll');
523	      phoneScroll('short');
524	      addOption('Scroll length', { Long: 'long', Medium: 'medium', Short: 'short' }, 'short', (v) => {
525	        phoneScroll(v);
526	        redraw();
527	      });
528	      addOption('Surah name', { 'Under the book': 'under', 'On the page': 'page' }, 'under', setData('phoneLeft'));
529	    }
530	  }
