532	  // Finishing the opening ------------------------------------------------------------
533	
534	  function onScroll() {
535	    schedule();
536	    if (autoScroll) return; // the page's own scrolling
537	    direction = Math.sign(scrollY - lastY) || direction;
538	    lastY = scrollY;
539	    waitToFinish();
540	  }
541	
542	  function waitToFinish() {
543	    clearTimeout(finishTimer);
544	    finishTimer = setTimeout(finishOpening, FINISH_WAIT);
545	  }
546	
547	  function finishOpening() {
548	    if (finish === 'off' || touching || autoScroll || reduceMotion.matches || !visible) return;
549	    const progress = (targetScroll() - REST) / OPEN;
550	    if (progress <= 0.002 || progress >= 0.998) return; // closed or open already
551	    const open = finish === 'nearest' ? progress >= 0.5 : direction > 0;
552	    scrollToScreens(open ? REST + OPEN : REST);
553	  }
554	
555	  // Scrolls the page to a point on the hero's timeline, easing in and out.
556	  function scrollToScreens(s) {
557	    const range = hero.offsetHeight - stage.offsetHeight;
558	    const from = scrollY;
559	    const distance = hero.getBoundingClientRect().top + scrollY + (s / TOTAL) * range - from;
560	    const duration = Math.max(300, (1000 * Math.abs(distance)) / innerHeight / finishSpeed); // a short finish still eases
561	    const start = performance.now();
562	    const tick = (now) => {
563	      const t = Math.min(1, (now - start) / duration);
564	      const eased = t < 0.5 ? 4 * t * t * t : 1 - (2 - 2 * t) ** 3 / 2;
565	      scrollTo(0, from + distance * eased);
566	      autoScroll = t < 1 ? requestAnimationFrame(tick) : 0;
567	      if (!autoScroll) lastY = scrollY;
568	    };
569	    autoScroll = requestAnimationFrame(tick);
570	  }
571	
572	  // Any scrolling by the visitor takes over from the page's own.
573	  function takeOver() {
574	    cancelAnimationFrame(autoScroll);
575	    autoScroll = 0;
576	    lastY = scrollY;
577	  }
